let db=load();
let session=null; // Only a verified server session or an explicit demo action can enter. 
let page=location.hash.slice(1)||'dashboard', filter='',batchFilter='all',statusFilter='all',tab='general';
const $=(s)=>document.querySelector(s),$$=(s)=>[...document.querySelectorAll(s)];
const t=(s)=>translate(s,db.settings.language),e=(s)=>esc(t(s));
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',students:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',batches:'M3 7l9-4 9 4-9 4z M3 12l9 4 9-4 M3 17l9 4 9-4',attendance:'M9 3h6v4H9z M9 5H5v16h14V5h-4 M8 13l3 3 5-6',assignments:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',materials:'M3 5h7l2 2h9v13H3z M8 12h8 M8 16h5',exams:'M8 3H5v18h14V3h-3 M9 2h6v4H9z M8 11h8 M8 15h5',quizzes:'M9 3h6 M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3 M7 15h10 M10 18h1',routine:'M12 8v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',notices:'M3 11v3h4l10 5V5L7 11z M7 14l2 7 M21 9v6',messages:'M21 11.5a8 8 0 0 1-8 8H7l-5 3 2-6a9 9 0 1 1 17-5z M8 10h8 M8 14h5',calendar:'M8 2v4 M16 2v4 M3 10h18 M3 4h18v17H3z M7 14h3 M14 14h3',fees:'M3 5h18v15H3z M3 9h18 M16 13h5v4h-5z',analytics:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',guardians:'M12 3l9 4v5q0 7-9 10Q3 19 3 12V7z M8 12l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15 M16 16l5 5',bell:'M18 8a6 6 0 0 0-12 0v6l-3 4h18l-3-4z M10 21h4',down:'M6 9l6 6 6-6',close:'M6 6l12 12 M6 18L18 6',check:'M5 12l4 4L19 6',menu:'M4 6h16 M4 12h16 M4 18h16',logout:'M9 5H3v14h6 M13 8l4 4-4 4 M8 12h13',edit:'M15 4l5 5 M4 20l4-1L21 6l-5-5L3 14z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',ai:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',clock:'M12 8v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',pin:'M8 3h8l-1 6 4 4H5l4-4z M12 13v8',file:'M14 2H5v20h14V7z M14 2v5h5',eye:'M2 12q10-14 20 0-10 14-20 0 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'M12 3l9 4v5q0 7-9 10Q3 19 3 12V7z',teachers:'M5 3h16v12H9 M13 19h6 M16 15v4 M5 10a3 3 0 1 0 0 6 3 3 0 0 0 0-6 M1 22v-2q4-5 8 0v2',plans:'M12 2l10 6-10 6L2 8z M2 13l10 6 10-6 M2 18l10 6 10-6',billing:'M4 3h16v18l-4-2-4 2-4-2-4 2z M8 8h8 M8 12h6',audit:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const btn=(label,action,cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${e(label)}</button>`;
const badge=(text)=>`<span class="badge ${['Active','Present','Paid','Published','Reviewed','Submitted'].includes(text)?'green':['Absent','Suspended','Overdue','Returned'].includes(text)?'red':['Late','Pending','Due','Trial','Draft'].includes(text)?'amber':''}">${e(text)}</span>`;
const initials=(name)=>esc(name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join(''));
const avatar=(name,i=0)=>`<span class="avatar ${i%3===1?'purple':i%3===2?'amber':''}">${initials(name)}</span>`;
const money=(n)=>new Intl.NumberFormat(db.settings.language==='bn'?'bn-BD':'en-BD',{style:'currency',currency:'BDT',currencyDisplay:'narrowSymbol',maximumFractionDigits:0}).format(n);
const num=(n)=>new Intl.NumberFormat(db.settings.language==='bn'?'bn-BD':'en-US').format(n);
const date=(s)=>s?new Date(s.length===10?s+'T12:00':s).toLocaleDateString(db.settings.language==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const time=(s)=>new Date('2000-01-01T'+s).toLocaleTimeString(db.settings.language==='bn'?'bn-BD':'en-US',{hour:'numeric',minute:'2-digit'});
const me=()=>session?.role==='student'?db.students.find(x=>x.id===session.id):db.teachers.find(x=>x.id===session?.teacherId);
const teacher=()=>db.teachers.find(x=>x.id===session?.teacherId);
const isStudent=()=>session?.role==='student',isAdmin=()=>session?.role==='admin';
const own=(key)=>db[key].filter(x=>isAdmin()||x.teacherId===session?.teacherId);
const visible=(key)=>own(key).filter(x=>!isStudent()||(key!=='students'||x.id===session.id)&&(key!=='marks'||db.exams.find(e=>e.id===x.examId)?.status==='Published')&&(key==='students'||!x.studentId||x.studentId===session.id)&&(!x.batchId||x.batchId==='all'||me()?.batchIds.includes(x.batchId))&&(!x.status||x.status!=='Draft'));
const students=()=>own('students').filter(x=>x.status==='Active');
const batches=()=>own('batches').filter(x=>x.status==='Active');
const batchName=(id)=>id==='all'?t('All batches'):db.batches.find(x=>x.id===id)?.name||'—';
const studentName=(id)=>db.students.find(x=>x.id===id)?.name||'—';
const labels={dashboard:'Dashboard',students:'Students',batches:'Batches',attendance:'Attendance',assignments:'Assignments',materials:'Materials',exams:'Exams',quizzes:'Quizzes',routine:'Routine',notices:'Notices',messages:'Messages',calendar:'Calendar',fees:'Fees',analytics:'Analytics',guardians:'Guardians',ai:'AI Studio',settings:'Settings',teachers:'Teachers',plans:'Plans',billing:'Billing',audit:'Audit log'};
const featureMap={messages:'messages',materials:'materials',quizzes:'quizzes',ai:'ai',fees:'fees',guardians:'guardians'};
function allowed(p){if(!session)return false;if(isAdmin())return ['dashboard','teachers','plans','billing','notices','audit','settings'].includes(p);if(!isAdmin()&&['teachers','plans','billing','audit'].includes(p))return false;if(isStudent()&&['students','batches','analytics','guardians','ai','teachers','plans','billing','audit'].includes(p))return false;return !featureMap[p]||teacher()?.features[featureMap[p]];}
function save(action,entity,id,before=null){db.audit.unshift({id:uid(),teacherId:session?.teacherId,actor:isAdmin()?'Super Admin':me()?.name||'Demo',action,entity,recordId:id,before,created:new Date().toISOString()});try{persist(db);}catch{toast(t('Storage')+' '+(db.settings.language==='bn'?'পূর্ণ। ব্যাকআপ নিন।':'is full. Export a backup.'),true);throw new Error('Local storage full');}}
function toast(message,error=false){const el=document.createElement('div');el.className='toast';el.textContent=message;if(error)el.style.borderColor='var(--red)';$('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function go(p){closeModal();page=p;filter='';batchFilter='all';statusFilter='all';tab=p==='settings'?'general':'';location.hash=p;render();}
function render(){document.documentElement.lang=db.settings.language;document.body.className=[db.settings.theme==='light'?'light':'',!db.settings.motion?'no-motion':''].join(' ');if(session&&!isAdmin()&&!session.impersonating&&(!teacher()||teacher().status==='Suspended'||isStudent()&&me()?.status!=='Active')){session=null;sessionStorage.setItem('sl-session','null');}if(!session){renderLogin();return;}if(!labels[page])page='dashboard';const nav=(list)=>list.filter(allowed).map(p=>`<button class="nav-item ${page===p?'active':''}" data-go="${p}">${icon(p)}<span>${e(labels[p])}</span>${p==='messages'&&own('messages').some(m=>!m.read&&m.sender!==session.id)?'<span class="count">•</span>':''}</button>`).join('');
$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="favicon.svg" alt=""><div><strong>Science Lab<span style="color:var(--accent)">.</span></strong><small>Coaching workspace</small></div></div><div class="nav-scroll"><div class="nav-label">${e(isAdmin()?'Platform':'Workspace')}</div>${nav(isAdmin()?['dashboard','teachers','plans','billing']:['dashboard'])}${!isAdmin()?`<div class="nav-label">${e('Classroom')}</div>${nav(['students','batches','attendance','assignments','materials','exams','quizzes','routine'])}`:''}<div class="nav-label">${e('Management')}</div>${nav(isAdmin()?['notices','audit','ai','connections']:['notices','messages','calendar','fees','analytics','guardians','ai','online','connections'])}</div><div class="sidebar-footer">${nav(['settings'])}<button class="nav-item" data-action="switch">${icon('logout')}${e('Switch workspace')}</button><div class="local-label"><i class="dot"></i>${e('Local workspace')}<span style="margin-left:auto">v1.0</span></div></div></aside><main class="main">${session.impersonating?`<div class="impersonation">${e('View as teacher')}: ${esc(me()?.name)}${btn('Super Admin','return-admin','small')}</div>`:''}<header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="${e('Open')}">${icon('menu')}</button><span>${icon('batches')}</span><span>${esc(isAdmin()?'Platform':teacher()?.coaching||'Science Lab')}</span><span>/</span><b>${e(labels[page])}</b></div><div class="top-actions"><button class="search-button" data-action="search">${icon('search')}<span>${e('Search anything…')}</span><kbd>Ctrl K</kbd></button><button class="btn ghost small" data-action="language" aria-label="${e('Language')}">${db.settings.language==='en'?'বাংলা':'EN'}</button><button class="icon-button" data-action="notifications" aria-label="${e('Notifications')}">${icon('bell')}<i class="notification-dot"></i></button><button class="btn ghost small" data-go="settings" aria-label="${e('Profile')}">${avatar(isAdmin()?'Super Admin':me()?.name||'Teacher')}</button></div></header><div class="content intro-animation" id="page-content">${allowed(page)?renderPage():`<div class="empty">${icon('shield')}<h3>${e('Feature unavailable')}</h3><p>${e('Contact your platform administrator to enable this module.')}</p></div>`}<footer class="page-footer"><span>${icon('quizzes')}Science Lab · ${e('Stay curious. Keep learning.')}</span><span><i class="dot"></i>${e('Data stays in this browser')}</span></footer></div></main></div>`;
bindPage();}
function heading(title,subtitle='',actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${e(title)}</h1>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
function stat(title,value,foot,ico){return `<div class="stat"><div class="stat-top">${e(title)}${icon(ico)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div><svg class="stat-line" viewBox="0 0 70 30"><path d="M1 27L12 22 20 24 30 13 39 17 49 8 58 12 69 2" fill="none" stroke="var(--accent)" stroke-width="1.5"/></svg></div>`;}
function panel(title,body,link='',cls=''){return `<section class="panel ${cls}"><div class="panel-header"><h2>${e(title)}</h2>${link}</div><div class="panel-body">${body}</div></section>`;}
function empty(){return `<div class="empty">${icon('quizzes')}<h3>${e(filter?'Nothing matches your search':'No records yet')}</h3><p>${e('Add your first record to get started.')}</p></div>`;}
function pulse(){const exams=visible('exams').filter(x=>x.status==='Published').slice(-6);const vals=exams.map(x=>{const marks=visible('marks').filter(m=>m.examId===x.id);return marks.length?Math.round(marks.reduce((s,m)=>s+m.marks/x.total*100,0)/marks.length):0;});const points=vals.map((v,i)=>`${45+i*(440/Math.max(vals.length-1,1))},${160-v*1.3}`).join(' ');return `<div class="chart-legend"><span><i></i>${e('Average')}</span><span>${e('Last 6 exams')}</span></div><svg class="chart" viewBox="0 0 520 200" role="img" aria-label="${e('Learning pulse')}"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#62ddc1" stop-opacity=".22"/><stop offset="1" stop-color="#62ddc1" stop-opacity="0"/></linearGradient></defs>${[40,60,80,100].map(v=>`<line class="chart-grid" x1="35" x2="500" y1="${160-v*1.3}" y2="${160-v*1.3}"/><text x="0" y="${164-v*1.3}">${v}</text>`).join('')}${vals.length?`<polygon points="45,168 ${points} ${45+(vals.length-1)*(440/Math.max(vals.length-1,1))},168" fill="url(#fade)"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2.5"/>${vals.map((v,i)=>`<circle cx="${45+i*(440/Math.max(vals.length-1,1))}" cy="${160-v*1.3}" r="4" fill="var(--panel)" stroke="var(--accent)" stroke-width="2"/><text x="${45+i*(440/Math.max(vals.length-1,1))}" y="190" text-anchor="middle">${date(exams[i].date).replace(/ \d{4}/,'')}</text>`).join('')}`:''}</svg>`;}
function scheduleRows(){const rows=visible('routine').filter(r=>Number(r.day)===new Date().getDay()).sort((a,b)=>a.start.localeCompare(b.start));return rows.length?rows.map((r,i)=>`<div class="schedule-row"><div class="schedule-time">${esc(time(r.start))}<small>${esc(time(r.end))}</small></div><span class="subject-symbol ${i%3===1?'purple':i%3===2?'amber':''}">${i%3===0?'φ':i%3===1?'C':'π'}</span><div class="row-main"><strong>${esc(r.subject)}</strong><small>${esc(batchName(r.batchId))} · ${esc(r.room)}</small></div>${badge('Upcoming')}<button class="icon-button" data-action="${isStudent()?'detail:routine:':'att-batch:'}${isStudent()?r.id:r.batchId}" aria-label="${e('Open')}">${icon('arrow')}</button></div>`).join(''):`<div class="empty">${e('No classes scheduled today')}</div>`;}
function dashboard(){if(isAdmin())return adminDashboard();const records=visible('attendance'),rate=attendanceRate(records),due=isStudent()?outstanding(db,session.id):students().reduce((s,x)=>s+outstanding(db,x.id),0);const pending=visible('assignments').filter(x=>x.status==='Published'&&(!isStudent()||!db.submissions.some(s=>s.assignmentId===x.id&&s.studentId===session.id)));const awaiting=own('submissions').filter(s=>s.status==='Submitted');const notice=visible('notices').filter(n=>!n.expires||n.expires>=today()).sort((a,b)=>Number(b.pinned)-Number(a.pinned))[0];const fullDate=new Date().toLocaleDateString(db.settings.language==='bn'?'bn-BD':'en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});return heading(isStudent()?'Your week, at a glance.':'Your teaching, in focus.',t('Good morning')+', '+((me()?.name||'').split(' ')[isStudent()?0:1]||(me()?.name||''))+'. '+t('A little structure. A lot of possibility.'),isStudent()?btn('Upcoming work','go:assignments','primary','assignments'):btn('Take attendance','go:attendance','','attendance')+btn('New assignment','create:assignments','primary','plus'),fullDate)+`<div class="stats">${stat(isStudent()?'Active batches':'Active students',num(isStudent()?me().batchIds.length:students().length),`<em>●</em> ${e(isStudent()?'Students enrolled':'Active')}`,isStudent()?'batches':'students')}${stat(isStudent()?'Assignments':'Active batches',num(isStudent()?pending.length:batches().length),e(isStudent()?'Pending':'Classroom'),'batches')}${stat('Attendance rate',num(rate)+'<span style="font-size:20px">%</span>',e('Attendance history'),'attendance')}${stat('Outstanding fees',money(due),e('Due')+' · '+new Date().toLocaleDateString(db.settings.language==='bn'?'bn-BD':'en',{month:'long'}),'fees')}</div><div class="dashboard-grid"><div class="stack">${panel('Today’s schedule',scheduleRows(),`<button class="text-link" data-go="routine">${e('View routine')} ↗</button>`)}${panel('Learning pulse',pulse(),`<span class="badge">${e('Overview')}</span>`)}${panel('Recent activity',own('audit').slice(0,3).map(a=>`<div class="activity-row">${avatar(a.actor)}<div class="row-main"><strong>${e(a.action)} · ${e(labels[a.entity]||a.entity)}</strong><small>${esc(a.actor)}</small></div><time>${date(a.created)}</time></div>`).join('')||empty())}</div><div class="stack">${panel('Needs your attention',`<div class="attention-row"><span class="attention-icon">${icon('assignments')}</span><div class="row-main"><strong>${num(isStudent()?pending.length:awaiting.length)} ${e(isStudent()?'Pending':'Submitted')}</strong><small>${e('Assignments')}</small></div><button class="text-link" data-go="assignments">↗</button></div><div class="attention-row"><span class="attention-icon red">${icon('fees')}</span><div class="row-main"><strong>${money(due)} ${e('Due')}</strong><small>${e('Fees')} · ${e('This month')}</small></div><button class="text-link" data-go="fees">↗</button></div><div class="attention-row"><span class="attention-icon" style="color:var(--purple);background:#b7a2f818">${icon('exams')}</span><div class="row-main"><strong>${e('Monthly assessment')}</strong><small>${date(visible('exams').find(x=>x.date>=today())?.date||db.exams.at(-1)?.date)}</small></div><button class="text-link" data-go="exams">↗</button></div>`)}${notice?panel('Notices',`<h3>${esc(notice.title)}</h3><p>${esc(notice.description)}</p><button class="text-link" style="padding:17px 0 0;color:var(--accent)" data-go="notices">${e('See all notices')} →</button><svg class="molecule" viewBox="0 0 100 100"><path d="M50 10L85 30v40L50 90 15 70V30z M50 10v40l35 20 M15 70l35-20" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="50" cy="10" r="7" fill="currentColor"/><circle cx="85" cy="70" r="7" fill="currentColor"/><circle cx="15" cy="70" r="7" fill="currentColor"/></svg>`,icon('pin'),'notice-feature'):''}${panel('Attendance breakdown',`<div class="donut-layout"><div class="donut" style="background:conic-gradient(var(--accent) 0 ${records.length?records.filter(a=>a.status==='Present').length/records.length*100:0}%,var(--amber) 0 ${rate}%,var(--red) 0 100%)"><div class="donut-value">${num(rate)}%<small>${e('Attendance')}</small></div></div><div class="legend-list">${['Present','Absent','Late'].map((s,i)=>`<div><i style="background:${['var(--accent)','var(--red)','var(--amber)'][i]}"></i>${e(s)}<b>${num(records.filter(r=>r.status===s).length)}</b></div>`).join('')}</div></div>`)}</div></div>`;}
function renderPage(){return renderFeaturePage();}
function bindPage(){bindFeatures();}
document.addEventListener('click',ev=>{const nav=ev.target.closest('[data-go]');if(nav){go(nav.dataset.go);return;}const el=ev.target.closest('[data-action]');if(el)act(el.dataset.action,el);});
function act(a){if(a==='language'){db.settings.language=db.settings.language==='en'?'bn':'en';persist(db);render();}else if(a==='menu')$('.sidebar').classList.toggle('open');else if(a.startsWith('go:'))go(a.slice(3));else featureAction(a);}
// Shared forms and local data operations.
let attDate=today(),attBatch='',attDraft={},feeMonth=month(),chatStudent='',calendarDate=new Date(),calendarMode='month',quizInterval=null,settingsTab='general';
const weekdays=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],weekdaysBn=['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
const dayName=n=>(db.settings.language==='bn'?weekdaysBn:weekdays)[Number(n)];
const canManage=()=>!isStudent(),currentUser=()=>session.role+':'+session.id;
function modal(title,body,actions='',wide=false){closeModal();$('#overlay').innerHTML='<dialog '+(wide?'style="width:min(950px,calc(100vw - 32px))"':'')+'><div class="modal-header"><h2>'+e(title)+'</h2><button class="icon-button" data-action="close" aria-label="'+e('Close')+'">'+icon('close')+'</button></div><div class="modal-body">'+body+'</div>'+(actions?'<div class="modal-actions">'+actions+'</div>':'')+'</dialog>';const d=$('dialog');d.showModal();d.addEventListener('cancel',ev=>{if(d.dataset.quiz){ev.preventDefault();toast(t('Submit quiz'));}});}
function closeModal(){if($('dialog')?.dataset.quiz)return;$('#overlay').innerHTML='';}
function confirmAction(title,callback,description='This action cannot be undone.'){modal(title,'<p class="detail-text">'+e(description)+'</p>',btn('Cancel','close')+'<button class="btn danger" id="confirm-action">'+e('Confirm')+'</button>');$('#confirm-action').onclick=()=>{callback();closeModal();render();};}
function field(name,label,type='text',value='',options=[],required=false,full=false){return '<label class="field '+(full?'full':'')+'"><span>'+e(label)+(required?' <span style="color:var(--accent)">*</span>':'')+'</span>'+(type==='textarea'?'<textarea name="'+name+'" '+(required?'required':'')+'>'+esc(value)+'</textarea>':type==='select'?'<select name="'+name+'" '+(required?'required':'')+'>'+options.map(o=>'<option value="'+esc(o.value??o)+'" '+(String(value)===String(o.value??o)?'selected':'')+'>'+esc(o.label??t(o))+'</option>').join('')+'</select>':'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+(required?'required':'')+' '+(type==='number'?'min="0" step="any"':'')+'>')+'</label>';}
function check(name,label,value=false){return '<label class="check-field"><input type="checkbox" name="'+name+'" '+(value?'checked':'')+'>'+e(label)+'</label>';}
const batchOptions=(all=false)=>(all?[{value:'all',label:t('All batches')}]:[]).concat(batches().map(b=>({value:b.id,label:b.name})));
const studentOptions=()=>students().map(s=>({value:s.id,label:s.name+' · '+s.studentId}));
function schema(entity,r={}){const cb=field('batchId','Batch','select',r.batchId||batches()[0]?.id,batchOptions(),true),ff='<label class="field full"><span>'+e('Attachment')+'</span><input type="file" name="uploads" multiple accept="'+db.settings.extensions.split(',').map(x=>'.'+x.trim()).join(',')+'"><small>'+e('Maximum upload (MB)')+': '+db.settings.uploadLimit+'</small></label>'+(r.files?.length?'<div class="field full">'+filesHTML(r.files)+'</div>':'');
switch(entity){
case 'students':return (!session.demo?field('email','Login email','email',r.email||'',[],true):'')+field('name','Name','text',r.name||'',[],true)+field('studentId','Student ID','text',r.studentId||'SL-'+Date.now().toString().slice(-6),[],true)+field('grade','Grade','text',r.grade||'12',[],true)+field('roll','Roll','number',r.roll||students().length+1,[],true)+field('phone','Phone','tel',r.phone||'')+field('guardian','Guardian name','text',r.guardian||'',[],true)+field('guardianPhone','Guardian WhatsApp','tel',r.guardianPhone||'',[],true)+field('address','Address','text',r.address||'')+'<div class="field full"><span>'+e('Enrollments')+' *</span><div class="check-list">'+batches().map(b=>check('batchIds',b.name,r.batchIds?.includes(b.id)).replace('name="batchIds"','name="batchIds" value="'+b.id+'"')).join('')+'</div></div>'+field('status','Status','select',r.status||'Active',['Active','Archived'])+'<label class="field"><span>'+e('Profile')+'</span><input type="file" name="photo" accept="image/png,image/jpeg,image/webp"></label>';
case 'batches':return field('name','Name','text',r.name||'',[],true)+field('subject','Subject','text',r.subject||'',[],true)+field('schedule','Schedule','text',r.schedule||'',[],true)+field('capacity','Capacity','number',r.capacity||30,[],true)+field('fee','Monthly fee','number',r.fee??1500,[],true)+field('status','Status','select',r.status||'Active',['Active','Archived']);
case 'assignments':return field('title','Title','text',r.title||'',[],true,true)+cb+field('subject','Subject','text',r.subject||'',[],true)+field('instructions','Instructions','textarea',r.instructions||'',[],true,true)+field('deadline','Deadline','datetime-local',r.deadline||today()+'T23:59',[],true)+field('marks','Marks','number',r.marks??20,[],true)+field('status','Status','select',r.status||'Draft',['Draft','Published'])+check('late','Allow late submission',r.late)+field('url','Video link','url',r.url||'')+ff;
case 'materials':return field('title','Title','text',r.title||'',[],true,true)+cb+field('subject','Subject','text',r.subject||'',[],true)+field('chapter','Chapter','text',r.chapter||'',[],true,true)+field('description','Description','textarea',r.description||'',[],false,true)+field('url','Video link','url',r.url||'',[],false,true)+ff;
case 'exams':return field('title','Title','text',r.title||'',[],true,true)+cb+field('subject','Subject','text',r.subject||'',[],true)+field('date','Date','date',r.date||today(),[],true)+field('total','Total marks','number',r.total||100,[],true)+field('pass','Pass marks','number',r.pass??33,[],true)+field('status','Status','select',r.status||'Draft',['Draft','Published']);
case 'routine':return cb+field('subject','Subject','text',r.subject||'',[],true)+field('day','Day','select',r.day??new Date().getDay(),weekdays.map((d,i)=>({value:i,label:dayName(i)})),true)+field('room','Room','text',r.room||'Lab 01',[],true)+field('start','Start','time',r.start||'16:00',[],true)+field('end','End','time',r.end||'17:00',[],true)+field('url','Video link','url',r.url||'',[],false,true);
case 'notices':return field('title','Title','text',r.title||'',[],true,true)+field('description','Description','textarea',r.description||'',[],true,true)+(isAdmin()?'<div class="hint full">'+e('Global announcement')+'</div>':field('batchId','Batch','select',r.batchId||'all',batchOptions(true),true))+(!isAdmin()?field('studentId','Recipient','select',r.studentId||'',[{value:'',label:t('All students')},...studentOptions()]):'')+field('category','Category','select',r.category||'General',['General','Exam','Holiday','Urgent'])+field('expires','Expires on','date',r.expires||'')+check('pinned','Pinned',r.pinned)+ff;
case 'payments':return field('studentId','Student','select',r.studentId||students()[0]?.id,studentOptions(),true)+cb+field('month','Month','month',r.month||feeMonth,[],true)+field('amount','Amount','number',r.amount||'',[],true)+field('method','Method','select',r.method||'Cash',['Cash','bKash','Nagad','Bank'])+field('date','Date','date',r.date||today(),[],true)+field('reference','Reference','text',r.reference||'',[],false,true);
case 'teachers':return field('name','Name','text',r.name||'',[],true)+field('email','Email','email',r.email||'',[],true)+field('phone','Phone','tel',r.phone||'',[],true)+field('coaching','Coaching name','text',r.coaching||'',[],true)+field('plan','Plan','select',r.plan||'basic',db.plans.map(p=>({value:p.id,label:p.name})),true)+field('expiry','Subscription expiry','date',r.expiry||today(),[],true)+field('status','Status','select',r.status||'Active',['Active','Trial','Suspended']);
case 'plans':return field('name','Name','text',r.name||'',[],true)+field('price','Monthly price','number',r.price??499,[],true)+field('studentLimit','Student limit','number',r.studentLimit??30,[],true)+field('batchLimit','Batch limit','number',r.batchLimit??3,[],true)+field('storageLimit','Storage limit (MB)','number',r.storageLimit??20,[],true);
case 'billing':return field('teacherId','Teacher','select',r.teacherId||db.teachers[0]?.id,db.teachers.map(x=>({value:x.id,label:x.name})),true)+field('amount','Amount','number',r.amount||'',[],true)+field('month','Month','month',r.month||month(),[],true)+field('method','Method','select',r.method||'bKash',['Cash','bKash','Nagad','Bank'])+field('reference','Reference','text',r.reference||'',[],true)+field('date','Date','date',r.date||today(),[],true);
case 'events':return field('title','Title','text',r.title||'',[],true,true)+cb+field('date','Date','date',r.date||today(),[],true)+field('category','Category','select',r.category||'General',['General','Exam','Holiday'])+field('description','Description','textarea',r.description||'',[],false,true);
default:return '';}}
function canAccessRecord(entity,r){if(!r)return false;if(isAdmin())return ['teachers','plans','billing','notices','audit'].includes(entity);return r.teacherId===session.teacherId&&(!isStudent()||visible(entity).some(x=>x.id===r.id));}
function canEditEntity(entity){return isAdmin()?['teachers','plans','billing','notices'].includes(entity):!isStudent()&&!['teachers','plans','billing','audit','accounts'].includes(entity);}
async function uploadFiles(input,existing=[]){const selected=[...(input?.files||[])],list=[...existing],limit=Number(db.settings.uploadLimit)*1048576,quota=(teacher()?.storageLimit||100)*1048576;let used=Object.values(db).filter(Array.isArray).flat().filter(r=>r.teacherId===session.teacherId).reduce((s,r)=>s+(r.files||[]).reduce((n,f)=>n+f.size,0),0);for(const file of selected){const ext=file.name.split('.').pop().toLowerCase();if(!db.settings.extensions.split(',').map(x=>x.trim()).includes(ext))throw Error((db.settings.language==='bn'?'অনুমোদিত ফাইল নয়: ':'File type is not allowed: ')+ext);if(file.size>limit)throw Error(t('Maximum upload (MB)')+': '+db.settings.uploadLimit);if(used+file.size>quota)throw Error(t('Storage limit (MB)')+': '+(teacher()?.storageLimit||100));const id=uid();await putFile(file,id);list.push({id,name:file.name,type:file.type,size:file.size});used+=file.size;}return list;}
function filesHTML(files=[]){return '<div class="file-list">'+files.map(f=>'<button class="file-chip" type="button" data-action="file:'+f.id+'">'+esc(f.name)+' · '+Math.ceil(f.size/1024)+' KB</button>').join('')+'</div>';}
function safeURL(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function createCredentials(role,record){const username=role==='teacher'?record.email:record.studentId,password='Lab!'+crypto.getRandomValues(new Uint32Array(2)).join('').slice(0,10),salt=uid();db.accounts.push({id:uid(),role,ref:record.id,teacherId:role==='teacher'?record.id:record.teacherId,username,salt,hash:await passwordHash(password,salt),forceReset:true});persist(db);modal('Temporary credentials','<p class="hint">'+(db.settings.language==='bn'?'প্রথম লগইনে পাসওয়ার্ড পরিবর্তন করতে হবে। লগইন তথ্য নিজে সংশ্লিষ্ট ব্যক্তিকে দিন।':'A password change is required at first login. Share these credentials with the account owner yourself.')+'</p><div class="credential">'+e('Username')+': '+esc(username)+'<br>'+e('Password')+': '+esc(password)+'</div>',btn('Close','close'));}
function validateRecord(entity,r,original){const fail=(en,bn)=>{throw Error(db.settings.language==='bn'?bn:en);};if(['students','teachers'].includes(entity)&&!(/^\+?[0-9 ()-]{10,18}$/).test(entity==='students'?r.guardianPhone:r.phone))fail('Enter a valid phone number.','সঠিক ফোন নম্বর দিন।');if(entity==='students'){if(!r.batchIds.length)fail('Select at least one batch.','অন্তত একটি ব্যাচ নির্বাচন করুন।');if(db.students.some(s=>s.studentId===r.studentId&&s.id!==r.id))fail('This student ID already exists.','এই শিক্ষার্থী আইডি আগে থেকেই আছে।');if((!original||original.status!=='Active')&&r.status==='Active'&&students().length>=teacher().studentLimit)fail('Student limit reached.','শিক্ষার্থী সীমা পূর্ণ।');for(const id of r.batchIds){const b=batches().find(x=>x.id===id);if(!b)fail('Select an active batch.','সক্রিয় ব্যাচ নির্বাচন করুন।');if(students().filter(s=>s.id!==r.id&&s.batchIds.includes(id)).length>=b.capacity)fail('Batch capacity reached: '+b.name,'ব্যাচের আসন পূর্ণ: '+b.name);}}
if(entity==='batches'&&(!original||original.status!=='Active')&&r.status==='Active'&&batches().length>=teacher().batchLimit)fail('Batch limit reached.','ব্যাচ সীমা পূর্ণ।');if(entity==='batches'&&r.capacity<students().filter(s=>s.batchIds.includes(r.id)).length)fail('Capacity is below current enrollment.','ভর্তি শিক্ষার্থীর চেয়ে আসন কম হতে পারে না।');if(entity==='teachers'&&db.teachers.some(x=>x.email===r.email&&x.id!==r.id))fail('Email already exists.','ইমেইলটি আগে থেকেই আছে।');if(entity==='exams'&&(r.total<=0||r.pass>r.total))fail('Pass marks must not exceed positive total marks.','পাস নম্বর পূর্ণমানের বেশি হতে পারবে না।');if(entity==='exams'&&db.marks.some(m=>m.examId===r.id&&m.marks>r.total))fail('Existing marks exceed this total.','সংরক্ষিত নম্বর পূর্ণমানের বেশি।');if(entity==='routine'){if(r.start>=r.end)fail('End time must be after start time.','শেষ সময় শুরুর পরে হতে হবে।');if(own('routine').some(x=>x.id!==r.id&&Number(x.day)===Number(r.day)&&r.start<x.end&&r.end>x.start))fail('This class overlaps an existing class.','এই সময়ে আরেকটি ক্লাস আছে।');}if(entity==='payments'){if(!students().find(s=>s.id===r.studentId)?.batchIds.includes(r.batchId))fail('Student is not enrolled in this batch.','শিক্ষার্থী এই ব্যাচে ভর্তি নেই।');if(r.amount<=0)fail('Payment must be greater than zero.','পেমেন্ট শূন্যের বেশি হতে হবে।');const paid=own('payments').filter(p=>p.id!==r.id&&p.studentId===r.studentId&&p.batchId===r.batchId&&p.month===r.month).reduce((s,p)=>s+p.amount,0);if(paid+r.amount>Number(db.batches.find(b=>b.id===r.batchId).fee))fail('Payment exceeds the remaining fee.','পেমেন্ট বকেয়ার বেশি হচ্ছে।');}if(entity==='billing'&&r.amount<=0)fail('Payment must be positive.','পেমেন্ট শূন্যের বেশি হতে হবে।');}
function editRecord(entity,id){if(!canEditEntity(entity))return;const original=id?db[entity].find(x=>x.id===id):null;if(id&&!canAccessRecord(entity,original))return;if(entity==='quizzes'){editQuiz(id);return;}if(['assignments','exams','materials','routine','events','payments'].includes(entity)&&!batches().length){toast(t('Create batch'),true);return;}modal((id?t('Edit'):t('Create'))+' · '+t(labels[entity]||entity),'<form id="record-form"><div class="form-grid">'+schema(entity,original||{})+'</div><div class="error" id="form-error" role="alert"></div><div class="actions" style="justify-content:flex-end;margin-top:22px">'+btn('Cancel','close')+'<button class="btn primary" type="submit">'+e('Save')+'</button></div></form>');$('#record-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,submit=form.querySelector('[type=submit]');submit.disabled=true;try{const data=Object.fromEntries(new FormData(form));delete data.uploads;delete data.photo;const r={...(original||{}),...data,id:original?.id||uid(),teacherId:original?.teacherId||(isAdmin()?null:session.teacherId)};for(const key of ['capacity','fee','roll','marks','total','pass','day','amount','price','studentLimit','batchLimit','storageLimit'])if(key in r)r[key]=Number(r[key]);if(entity==='students')r.batchIds=new FormData(form).getAll('batchIds');if(entity==='assignments')r.late=form.elements.late.checked;if(entity==='notices'){r.pinned=form.elements.pinned.checked;if(r.studentId)r.batchId='all';if(isAdmin()){r.teacherId=null;r.batchId='all';r.global=true;}}if(entity==='billing')r.teacherId=data.teacherId;if(entity==='teachers'){const plan=db.plans.find(p=>p.id===r.plan);Object.assign(r,{studentLimit:plan.studentLimit,batchLimit:plan.batchLimit,storageLimit:plan.storageLimit,features:original?.features||{messages:true,materials:true,quizzes:true,ai:false,fees:true,guardians:false}});r.joined=original?.joined||today();}validateRecord(entity,r,original);if(form.elements.uploads)r.files=await uploadFiles(form.elements.uploads,original?.files);if(form.elements.photo?.files.length){r.files=await uploadFiles(form.elements.photo,[]);r.photo=r.files[0]?.id;}r.created=r.created||today();if(!session.demo&&!original&&['students','teachers'].includes(entity)){await cloud.flush();const credentials=await cloud.request('account',{role:entity==='teachers'?'teacher':'student',record:r});closeModal();await refreshCloud();showCredentials(credentials);return;}const before=original?structuredClone(original):null;if(original)Object.assign(original,r);else db[entity].unshift(r);save(original?'Edit':'Create',entity,r.id,before);if(['assignments','notices','exams'].includes(entity)&&r.status!=='Draft')queueForRecord(entity,r);closeModal();render();toast(t('Saved successfully'));if(!original&&['students','teachers'].includes(entity))await createCredentials(entity==='teachers'?'teacher':'student',r);}catch(error){$('#form-error').textContent=error.message;submit.disabled=false;}};}
function queueForRecord(entity,r){if(!teacher()?.features.guardians)return;const targets=r.studentId?[db.students.find(s=>s.id===r.studentId)]:students().filter(s=>!r.batchId||r.batchId==='all'||s.batchIds.includes(r.batchId));for(const s of targets.filter(Boolean))db.queue.unshift({id:uid(),teacherId:session.teacherId,studentId:s.id,type:labels[entity]||entity,text:s.name+': '+(r.title||r.status||entity),created:new Date().toISOString(),status:'Not sent'});persist(db);}
function removeRecord(entity,id,archive=false){const r=db[entity]?.find(x=>x.id===id);if(!canEditEntity(entity)||!canAccessRecord(entity,r))return;if(entity==='plans'&&db.teachers.some(x=>x.plan===id)){toast(db.settings.language==='bn'?'ব্যবহৃত প্ল্যান মুছতে পারবেন না।':'This plan is assigned to a teacher.',true);return;}if(entity==='quizzes'&&db.attempts.some(a=>a.quizId===id)){toast(db.settings.language==='bn'?'কুইজে উত্তর জমা হয়েছে।':'This quiz already has attempts.',true);return;}if(archive&&r.status==='Archived'){try{validateRecord(entity,{...r,status:'Active'},r);}catch(err){toast(err.message,true);return;}}confirmAction(archive?(r.status==='Archived'?'Restore':'Archive'):'Delete',()=>{const before=structuredClone(r);if(archive)r.status=r.status==='Archived'?'Active':'Archived';else{db[entity]=db[entity].filter(x=>x.id!==id);if(entity==='teachers'){for(const key of Object.keys(db))if(Array.isArray(db[key])&&!['audit','plans','teachers'].includes(key))db[key]=db[key].filter(x=>x.teacherId!==id);db.accounts=db.accounts.filter(a=>a.ref!==id);}if(entity==='assignments')db.submissions=db.submissions.filter(x=>x.assignmentId!==id);if(entity==='exams')db.marks=db.marks.filter(x=>x.examId!==id);}save(archive?'Archive':'Delete',entity,id,before);toast(t('Saved successfully'));},archive?'This record will be archived.':'This action cannot be undone.');}
function recordActions(entity,r,extra=''){return '<div class="table-actions">'+extra+(canManage()?'<button class="icon-button" data-action="edit:'+entity+':'+r.id+'" aria-label="'+e('Edit')+'">'+icon('edit')+'</button><button class="icon-button" data-action="'+(['students','batches'].includes(entity)?'archive':'delete')+':'+entity+':'+r.id+'" aria-label="'+e(['students','batches'].includes(entity)?(r.status==='Archived'?'Restore':'Archive'):'Delete')+'">'+icon('trash')+'</button>':'')+'</div>';}
function toolbar(showBatch=true,showStatus=false,extra=''){return '<div class="toolbar"><input id="list-search" class="search-input" placeholder="'+e('Search')+'…" value="'+esc(filter)+'" aria-label="'+e('Search')+'">'+(showBatch?'<select id="batch-filter" aria-label="'+e('Batch')+'">'+batchOptions(true).map(b=>'<option value="'+b.value+'" '+(batchFilter===b.value?'selected':'')+'>'+esc(b.label)+'</option>').join('')+'</select>':'')+(showStatus?'<select id="status-filter" aria-label="'+e('Status')+'">'+['all','Active','Archived'].map(s=>'<option value="'+s+'" '+(statusFilter===s?'selected':'')+'>'+e(s==='all'?'All':s)+'</option>').join('')+'</select>':'')+extra+'</div>';}
function filtered(list){return list.filter(r=>(!filter||[r.name,r.title,r.studentId,r.subject,r.guardian,r.grade].join(' ').toLowerCase().includes(filter.toLowerCase()))&&(batchFilter==='all'||r.batchId===batchFilter||r.batchIds?.includes(batchFilter))&&(statusFilter==='all'||r.status===statusFilter));}
function renderFeaturePage(){switch(page){case'dashboard':return dashboard();case'students':return studentsPage();case'batches':return batchesPage();case'attendance':return attendancePage();case'assignments':case'materials':case'exams':case'quizzes':case'notices':return contentPage(page);case'routine':return routinePage();case'fees':return feesPage();case'calendar':return calendarPage();case'messages':return messagesPage();case'analytics':return analyticsPage();case'settings':return settingsPage();case'teachers':return teachersPage();case'plans':return plansPage();case'billing':return billingPage();case'audit':return auditPage();case'guardians':return guardiansPage();case'ai':return aiPage();default:return dashboard();}}

function studentsPage(){const rows=filtered(own('students'));return heading('Students',num(students().length)+' '+t('Active students'),btn('Import students','student-import','','file')+btn('Export CSV','export:students','','download')+btn('Add student','create:students','primary','plus'))+'<section class="panel">'+toolbar(true,true)+(rows.length?'<div class="table-wrap"><table><thead><tr>'+['Name','Batch','Guardian WhatsApp','Attendance','Fees','Status','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map((s,i)=>'<tr><td><div class="person">'+avatar(s.name,i)+'<div><button class="text-link" style="color:var(--text);font-size:12px;padding:0" data-action="profile:'+s.id+'">'+esc(s.name)+'</button><small>'+esc(s.studentId)+' · '+e('Grade')+' '+esc(s.grade)+'</small></div></div></td><td>'+s.batchIds.map(id=>'<div style="font-size:10px;margin:5px 0">'+esc(batchName(id))+'</div>').join('')+'</td><td><div>'+esc(s.guardianPhone)+'</div><small class="text-muted">'+esc(s.guardian)+'</small></td><td>'+num(attendanceRate(own('attendance').filter(a=>a.studentId===s.id)))+'%</td><td>'+(outstanding(db,s.id)>0?'<span style="color:var(--amber)">'+money(outstanding(db,s.id))+'</span>':badge('Paid'))+'</td><td>'+badge(s.status)+'</td><td>'+recordActions('students',s)+'</td></tr>').join('')+'</tbody></table></div>':empty())+'</section>';}
function batchesPage(){return heading('Batches',t('Your teaching, in focus.'),btn('Create batch','create:batches','primary','plus'))+'<section class="panel" style="margin-bottom:22px">'+toolbar(false,true)+'</section><div class="cards">'+(filtered(own('batches')).map((b,i)=>{const enrolled=students().filter(s=>s.batchIds.includes(b.id)).length;return '<article class="card"><div class="card-top"><span class="subject-symbol '+(i%3===1?'purple':i%3===2?'amber':'')+'">'+['φ','C','π'][i%3]+'</span>'+badge(b.status)+'</div><h3>'+esc(b.name)+'</h3><p>'+esc(b.subject)+'</p><div class="card-meta"><span>'+esc(b.schedule)+'</span></div><div class="card-top" style="font-size:11px;margin:16px 0 9px"><span class="text-muted">'+num(enrolled)+' / '+num(b.capacity)+' '+e('Students')+'</span><span>'+money(b.fee)+' / '+e('Month')+'</span></div><div class="progress"><span style="width:'+Math.min(100,enrolled/b.capacity*100)+'%"></span></div><div class="card-bottom">'+btn('Students','batch-students:'+b.id,'small')+recordActions('batches',b)+'</div></article>';}).join('')||empty())+'</div>';}
function profile(id){const s=own('students').find(x=>x.id===id);if(!s||isStudent()&&s.id!==session.id)return;const records=own('attendance').filter(a=>a.studentId===id);modal('Student progress','<div class="person">'+avatar(s.name)+'<div><h3>'+esc(s.name)+'</h3><p class="subtitle">'+esc(s.studentId)+'</p></div></div><dl class="summary-list">'+[['Grade',s.grade],['Guardian name',s.guardian],['Guardian WhatsApp',s.guardianPhone],['Address',s.address],['Attendance',num(attendanceRate(records))+'%'],['Due',money(outstanding(db,id))]].map(([k,v])=>'<div><dt>'+e(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><h3 style="font-size:14px">'+e('Latest results')+'</h3>'+db.marks.filter(m=>m.studentId===id&&db.exams.find(e=>e.id===m.examId)?.status==='Published').map(m=>{const ex=db.exams.find(e=>e.id===m.examId);return '<div class="switch-row"><span>'+esc(ex.title)+'</span><strong>'+num(m.marks)+'/'+num(ex.total)+' · '+grade(m.marks/ex.total*100,db.settings.grading)+'</strong></div>';}).join('')+filesHTML(s.files),btn('Combined report','combined-report:'+id)+btn('Close','close'));}
function attendancePage(){if(isStudent())return studentAttendance();if(!batches().some(b=>b.id===attBatch))attBatch=batches()[0]?.id||'';const people=students().filter(s=>s.batchIds.includes(attBatch)),existing=own('attendance').filter(a=>a.batchId===attBatch&&a.date===attDate);attDraft=Object.fromEntries(existing.map(a=>[a.studentId,a.status]));return heading('Attendance',date(attDate),btn('Attendance history','att-history','','calendar')+btn('Mark all present','att-all','','check')+btn('Save attendance','att-save','primary','attendance'))+'<section class="panel"><div class="toolbar"><select id="att-batch" aria-label="'+e('Batch')+'">'+batchOptions().map(b=>'<option value="'+b.value+'" '+(attBatch===b.value?'selected':'')+'>'+esc(b.label)+'</option>').join('')+'</select><input type="date" id="att-date" value="'+attDate+'" max="'+today()+'" aria-label="'+e('Date')+'"><span class="text-muted" style="font-size:11px">'+num(people.length)+' '+e('Students')+'</span></div>'+(people.length?'<div class="table-wrap"><table><thead><tr><th>'+e('Student')+'</th><th>'+e('Student ID')+'</th><th>'+e('Status')+'</th></tr></thead><tbody>'+people.map((s,i)=>'<tr><td><div class="person">'+avatar(s.name,i)+esc(s.name)+'</div></td><td>'+esc(s.studentId)+'</td><td><div class="status-buttons" data-student="'+s.id+'">'+['Present','Absent','Late'].map(status=>'<button class="'+(attDraft[s.id]===status?'selected ':'')+status+'" data-action="mark:'+s.id+':'+status+'">'+e(status)+'</button>').join('')+'</div></td></tr>').join('')+'</tbody></table></div>':empty())+'</section>';}
function studentAttendance(){const rows=visible('attendance').filter(a=>a.date.startsWith(feeMonth));return heading('Attendance',t('Your week, at a glance.'),'<input type="month" id="fee-month" value="'+feeMonth+'" aria-label="'+e('Month')+'">')+'<div class="stats">'+['Present','Absent','Late'].map((s,i)=>stat(s,num(rows.filter(a=>a.status===s).length),feeMonth,['attendance','clock','clock'][i])).join('')+stat('Attendance rate',num(attendanceRate(rows))+'%',feeMonth,'analytics')+'</div>'+panel('Attendance history','<div class="attendance-calendar" style="display:grid;grid-template-columns:repeat(7,1fr);gap:10px">'+Array.from({length:new Date(Number(feeMonth.slice(0,4)),Number(feeMonth.slice(5)),0).getDate()},(_,i)=>{const day=feeMonth+'-'+String(i+1).padStart(2,'0'),a=rows.filter(x=>x.date===day);return '<div style="padding:13px 5px;text-align:center;border:1px solid var(--line);border-radius:7px"><div style="font-size:12px;margin-bottom:8px">'+num(i+1)+'</div>'+(a.map(x=>'<div title="'+esc(batchName(x.batchId))+'">'+badge(x.status)+'</div>').join('')||'<span class="text-muted">—</span>')+'</div>';}).join('')+'</div>');}
function saveAttendance(){if(isStudent()||!attBatch||attDate>today())return;const people=students().filter(s=>s.batchIds.includes(attBatch));if(!people.length)return;if(people.some(s=>!attDraft[s.id])){toast(db.settings.language==='bn'?'সবার হাজিরা চিহ্নিত করুন।':'Mark every student before saving.',true);return;}let changed=0;for(const s of people){const prev=db.attendance.find(a=>a.studentId===s.id&&a.batchId===attBatch&&a.date===attDate);if(prev?.status===attDraft[s.id])continue;const before=prev?structuredClone(prev):null,r={id:prev?.id||uid(),teacherId:session.teacherId,studentId:s.id,batchId:attBatch,date:attDate,status:attDraft[s.id]};if(prev)Object.assign(prev,r);else db.attendance.push(r);save(prev?'Edit':'Create','attendance',r.id,before);queueForRecord('attendance',r);changed++;}toast(t('Saved successfully')+' · '+num(changed));render();}
function attendanceHistory(){modal('Attendance history','<div class="form-grid">'+field('from','From','date',month()+'-01')+field('to','To','date',today())+'</div><div id="history-results" style="margin-top:20px"></div>',btn('Export CSV','export:attendance','','download')+btn('Print report','print-attendance','','file'),true);const update=()=>{const from=$('[name=from]').value,to=$('[name=to]').value,rows=own('attendance').filter(a=>a.date>=from&&a.date<=to&&(!attBatch||a.batchId===attBatch));$('#history-results').innerHTML='<div class="table-wrap"><table><thead><tr><th>'+e('Student')+'</th><th>'+e('Date')+'</th><th>'+e('Batch')+'</th><th>'+e('Status')+'</th></tr></thead><tbody>'+rows.sort((a,b)=>b.date.localeCompare(a.date)).map(a=>'<tr><td>'+esc(studentName(a.studentId))+'</td><td>'+date(a.date)+'</td><td>'+esc(batchName(a.batchId))+'</td><td>'+badge(a.status)+'</td></tr>').join('')+'</tbody></table></div>';};$('[name=from]').onchange=update;$('[name=to]').onchange=update;update();}
function contentPage(entity){const createLabels={assignments:'New assignment',materials:'Add material',exams:'New exam',quizzes:'Create quiz',notices:'Post notice'};let list=visible(entity);if(entity==='notices')list=[...list,...db.notices.filter(n=>n.global&&!list.some(x=>x.id===n.id))].filter(n=>!n.expires||n.expires>=today()).sort((a,b)=>Number(b.pinned)-Number(a.pinned));list=filtered(list);return heading(labels[entity],num(list.length)+' '+t(labels[entity]),canManage()?btn(createLabels[entity],'create:'+entity,'primary','plus'):(entity==='exams'?btn('Combined report','combined-report:'+session.id,'primary','file'):''))+'<section class="panel" style="margin-bottom:22px">'+toolbar(!isAdmin())+'</section><div class="cards">'+(list.map((r,i)=>{let meta='',action='';if(entity==='assignments'){const sub=db.submissions.find(s=>s.assignmentId===r.id&&s.studentId===session.id);meta=date(r.deadline)+' · '+num(r.marks)+' '+t('Marks');action=btn(isStudent()?'Open':'View submissions','assignment:'+r.id,'small primary');if(isStudent())meta+=' · '+t(sub?.status||'Pending');}if(entity==='materials'){meta=r.chapter;action=btn('Open','detail:materials:'+r.id,'small primary');}if(entity==='exams'){meta=date(r.date)+' · '+num(r.total)+' '+t('Marks');action=btn(isStudent()?'View results':'Enter marks','exam:'+r.id,'small primary');}if(entity==='quizzes'){meta=num(r.questions.length)+' '+t('Questions')+' · '+num(r.duration)+' min';const attempt=db.attempts.find(a=>a.quizId===r.id&&a.studentId===session.id);action=btn(isStudent()?(attempt?'Review answers':'Start quiz'):'Analytics',isStudent()?(attempt?'quiz-review:':'quiz-start:')+r.id:'quiz-analytics:'+r.id,'small primary');}if(entity==='notices'){meta=date(r.created)+' · '+t(r.category);action=btn('Read','detail:notices:'+r.id,'small primary');}return '<article class="card"><div class="card-top"><span class="subject-symbol '+(i%3===1?'purple':i%3===2?'amber':'')+'">'+icon(entity)+'</span>'+(r.pinned?badge('Pinned'):badge(r.status||'Published'))+'</div><h3>'+esc(r.title)+'</h3><p>'+esc(t(r.subject||r.category||''))+'</p><div class="card-meta">'+esc(meta)+'</div><p style="font-size:10px">'+(r.global?e('Global announcement'):esc(batchName(r.batchId)))+'</p><div class="card-bottom">'+action+(canManage()&&(!r.global||isAdmin())?recordActions(entity,r):'')+'</div></article>';}).join('')||empty())+'</div>';}
function detail(entity,id){const r=db[entity]?.find(x=>x.id===id);if(!r||(!canAccessRecord(entity,r)&&!r.global))return;modal(r.title||r.subject,'<p class="subtitle">'+esc(r.subject||r.category||'')+' · '+esc(r.global?t('Global announcement'):batchName(r.batchId))+'</p><p class="detail-text" style="margin-top:18px">'+esc(r.description||r.instructions||[dayName(r.day),time(r.start||'00:00')+' – '+time(r.end||'00:00'),r.room].filter(Boolean).join('\n'))+'</p>'+filesHTML(r.files)+(safeURL(r.url)?'<a class="btn" href="'+esc(safeURL(r.url))+'" target="_blank" rel="noopener noreferrer">'+e('Open')+' ↗</a>':''),btn('Close','close'));if(entity==='notices'&&!db.readNotices.includes(currentUser()+':'+id)){db.readNotices.push(currentUser()+':'+id);persist(db);}}
function assignmentDetail(id){const r=visible('assignments').find(x=>x.id===id);if(!r)return;const existing=db.submissions.find(s=>s.assignmentId===id&&s.studentId===session.id);if(isStudent()){const overdue=Date.now()>new Date(r.deadline).getTime(),locked=overdue&&(!r.late||!!existing);modal(r.title,'<div class="card-meta"><span>'+date(r.deadline)+' '+new Date(r.deadline).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'</span><span>'+num(r.marks)+' '+e('Marks')+'</span>'+badge(existing?.status||'Pending')+'</div><p class="detail-text">'+esc(r.instructions)+'</p>'+filesHTML(r.files)+(safeURL(r.url)?'<a class="btn small" href="'+esc(safeURL(r.url))+'" target="_blank" rel="noopener noreferrer">'+e('Video link')+' ↗</a>':'')+(existing?.feedback?'<div class="hint section-gap"><b>'+e('Feedback')+'</b><br>'+esc(existing.feedback)+'<br>'+e('Marks')+': '+(existing.marks??'—')+'/'+r.marks+filesHTML(existing.feedbackFiles)+'</div>':'')+'<form id="submission-form" class="section-gap"><div class="form-grid">'+field('answer','Your answer','textarea',existing?.text||'',[],false,true)+'<label class="field full"><span>'+e('Attachment')+'</span><input type="file" name="uploads" multiple accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,image/*"></label><label class="field full"><span>'+(db.settings.language==='bn'?'ক্যামেরা':'Camera')+'</span><input type="file" name="camera" accept="image/*" capture="environment"></label></div>'+filesHTML(existing?.files)+'<div class="error" id="submission-error"></div>'+(locked?'<p class="hint warning">'+(db.settings.language==='bn'?'সময় শেষ; জমা বা পরিবর্তন করা যাবে না।':'The deadline has passed; submission changes are closed.')+'</p>':'<button type="submit" class="btn primary section-gap">'+e(existing?'Edit':'Submit')+'</button>')+'</form>');$('#submission-form').onsubmit=async ev=>{ev.preventDefault();if(locked)return;const form=ev.currentTarget;try{const text=form.answer.value.trim();let files=await uploadFiles(form.uploads,existing?.files);files=await uploadFiles(form.camera,files);if(!text&&!files.length)throw Error(db.settings.language==='bn'?'উত্তর বা ফাইল দিন।':'Add an answer or a file.');const sub={id:existing?.id||uid(),teacherId:session.teacherId,assignmentId:id,studentId:session.id,text,files,status:overdue?'Late':'Submitted',submittedAt:new Date().toISOString()},before=existing?structuredClone(existing):null;if(existing){delete existing.marks;delete existing.feedback;Object.assign(existing,sub);}else db.submissions.push(sub);save(existing?'Edit':'Submit','submissions',sub.id,before);closeModal();render();toast(t('Saved successfully'));}catch(error){$('#submission-error').textContent=error.message;}};}else{const people=students().filter(s=>s.batchIds.includes(r.batchId)),submissions=own('submissions').filter(s=>s.assignmentId===id);modal(r.title,'<p class="detail-text">'+esc(r.instructions)+'</p>'+filesHTML(r.files)+'<div class="toolbar" style="padding-inline:0"><select id="submission-status" aria-label="'+e('Status')+'">'+['All','Submitted','Pending','Late','Reviewed','Returned'].map(s=>'<option>'+e(s)+'</option>').join('')+'</select><span class="text-muted">'+submissions.length+'/'+people.length+' '+e('Submitted')+'</span></div><div id="submission-list"></div>',btn('Export ZIP','zip-submissions:'+id,'','download')+btn('Export CSV','export-submissions:'+id,'','download')+btn('Close','close'),true);const update=()=>{const selected=['All','Submitted','Pending','Late','Reviewed','Returned'][$('#submission-status').selectedIndex];$('#submission-list').innerHTML=people.map(s=>{const sub=submissions.find(x=>x.studentId===s.id);if(selected!=='All'&&(sub?.status||'Pending')!==selected)return '';return '<div class="switch-row"><div class="person">'+avatar(s.name)+'<div>'+esc(s.name)+'<p>'+(sub?date(sub.submittedAt):'—')+'</p></div></div><div class="actions">'+badge(sub?.status||'Pending')+(sub?btn('Open','review:'+sub.id,'small'):'')+'</div></div>';}).join('')||empty();};$('#submission-status').onchange=update;update();}}
function reviewSubmission(id){if(isStudent())return;const sub=own('submissions').find(s=>s.id===id);if(!sub)return;const assignment=db.assignments.find(a=>a.id===sub.assignmentId);modal(studentName(sub.studentId),'<p class="subtitle">'+esc(assignment.title)+'</p><p class="detail-text section-gap">'+esc(sub.text)+'</p>'+filesHTML(sub.files)+'<form id="review-form" class="section-gap"><div class="form-grid">'+field('marks','Marks','number',sub.marks??'',[],true)+field('status','Status','select',sub.status==='Returned'?'Returned':'Reviewed',['Reviewed','Returned'])+field('feedback','Feedback','textarea',sub.feedback||'',[],false,true)+'<label class="field full"><span>'+e('Feedback')+' · '+e('Attachment')+'</span><input name="voice" type="file" accept="audio/*"></label></div><div id="review-error" class="error"></div><button type="submit" class="btn primary section-gap">'+e('Save')+'</button></form>',btn('Close','close'));$('[name=marks]').max=assignment.marks;$('#review-form').insertAdjacentHTML('beforeend',btn('Record voice','voice:voice','small section-gap','clock'));$('#review-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget;try{const marks=Number(f.marks.value);if(marks<0||marks>assignment.marks)throw Error(t('Total marks')+': '+assignment.marks);const before=structuredClone(sub),feedbackFiles=await uploadFiles(f.voice,sub.feedbackFiles||[]);Object.assign(sub,{marks,feedback:f.feedback.value.trim(),status:f.status.value,feedbackFiles});save('Edit','submissions',id,before);closeModal();render();toast(t('Saved successfully'));}catch(err){$('#review-error').textContent=err.message;}};}
function examDetail(id){const exam=visible('exams').find(x=>x.id===id);if(!exam)return;if(isStudent()){reportCard(session.id,id);return;}const people=students().filter(s=>s.batchIds.includes(exam.batchId));modal(exam.title,'<p class="hint">'+e('Total marks')+': '+num(exam.total)+' · '+e('Pass marks')+': '+num(exam.pass)+' · '+badge(exam.status)+'</p><form id="marks-form"><div class="table-wrap"><table><thead><tr><th>'+e('Student')+'</th><th>'+e('Marks')+'</th><th>'+e('Feedback')+'</th><th>'+e('Report card')+'</th></tr></thead><tbody>'+people.map(s=>{const m=own('marks').find(m=>m.examId===id&&m.studentId===s.id);return '<tr><td>'+esc(s.name)+'</td><td><input aria-label="'+e('Marks')+' '+esc(s.name)+'" type="number" name="marks-'+s.id+'" min="0" max="'+exam.total+'" step="0.5" value="'+(m?.marks??'')+'" style="width:80px"></td><td><input name="remark-'+s.id+'" aria-label="'+e('Feedback')+' '+esc(s.name)+'" value="'+esc(m?.remark||'')+'"></td><td>'+btn('Open','report:'+s.id+':'+id,'small')+'</td></tr>';}).join('')+'</tbody></table></div><div class="error" id="marks-error"></div><div class="actions section-gap"><button type="submit" class="btn primary">'+e('Save changes')+'</button>'+btn(exam.status==='Published'?'Draft':'Publish','publish-exam:'+id)+'</div></form>',btn('Close','close'),true);$('#marks-form').onsubmit=ev=>{ev.preventDefault();for(const s of people){const value=ev.currentTarget.elements['marks-'+s.id].value,old=db.marks.find(m=>m.studentId===s.id&&m.examId===id);if(value===''){if(old){db.marks=db.marks.filter(m=>m.id!==old.id);save('Delete','marks',old.id,old);}continue;}const m={id:old?.id||uid(),teacherId:session.teacherId,studentId:s.id,examId:id,marks:Number(value),remark:ev.currentTarget.elements['remark-'+s.id].value},before=old?structuredClone(old):null;if(old)Object.assign(old,m);else db.marks.push(m);save(old?'Edit':'Create','marks',m.id,before);}toast(t('Saved successfully'));};}
function reportCard(studentId,examId){if(isStudent()&&studentId!==session.id)return;const student=own('students').find(s=>s.id===studentId),exam=visible('exams').find(e=>e.id===examId);if(!student||!exam)return;const m=own('marks').find(m=>m.studentId===studentId&&m.examId===examId);if(!m){toast(db.settings.language==='bn'?'এখনো নম্বর দেওয়া হয়নি।':'No marks have been entered yet.');return;}const position=own('marks').filter(x=>x.examId===examId&&x.marks>m.marks).length+1;modal('Report card','<div class="report" id="print-report"><div class="card-top"><div><h1>'+esc(teacher().coaching)+'</h1><p>'+e('Report card')+'</p></div><img src="favicon.svg" width="45" alt="Science Lab"></div><hr style="border:0;border-top:2px solid #16856e;margin:25px 0"><h2>'+esc(student.name)+'</h2><p style="margin-top:8px">'+esc(student.studentId)+' · '+e('Grade')+' '+esc(student.grade)+' · '+date(exam.date)+'</p><h3 style="margin-top:25px">'+esc(exam.title)+'</h3><table><thead><tr>'+['Subject','Marks','Total marks','Grade','Position'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody><tr><td>'+esc(exam.subject)+'</td><td>'+num(m.marks)+'</td><td>'+num(exam.total)+'</td><td>'+grade(m.marks/exam.total*100,db.settings.grading)+'</td><td>'+num(position)+'</td></tr></tbody></table><p>'+e('Feedback')+': '+esc(m.remark||'—')+'</p><p style="margin-top:60px;border-top:1px solid #bbb;padding-top:10px;width:180px">'+e('Signature')+' · '+esc(teacher().name)+'</p></div>',btn('Print report','print','','download')+btn('Close','close'),true);}

// Quiz authoring, timed attempts, and per-question analytics.
let questionDraft=[];
function editQuiz(id){if(isStudent())return;const original=id?own('quizzes').find(q=>q.id===id):null;if(id&&!original)return;if(id&&db.attempts.some(a=>a.quizId===id)){toast(db.settings.language==='bn'?'উত্তর জমা হওয়ার পর কুইজ বদলানো যাবে না।':'A quiz with attempts cannot be edited.',true);return;}if(!batches().length){toast(t('Create batch'));return;}questionDraft=structuredClone(original?.questions||[{id:uid(),text:'',options:['','','',''],answer:0,topic:''}]);modal(id?'Edit':'Create quiz','<form id="quiz-editor"><div class="form-grid">'+field('title','Title','text',original?.title||'',[],true,true)+field('batchId','Batch','select',original?.batchId||batches()[0].id,batchOptions(),true)+field('subject','Subject','text',original?.subject||'',[],true)+field('duration','Duration','number',original?.duration||10,[],true)+field('status','Status','select',original?.status||'Draft',['Draft','Published'])+field('opens','Opens at','datetime-local',original?.opens||today()+'T00:00',[],true)+field('closes','Closes at','datetime-local',original?.closes||today()+'T23:59',[],true)+check('random','Randomize questions',original?.random)+'</div><div id="question-editors"></div>'+btn('Add question','question-add','section-gap','plus')+'<div id="quiz-error" class="error"></div><button type="submit" class="btn primary section-gap">'+e('Save')+'</button></form>',btn('Close','close'),true);renderQuestionEditors();$('#quiz-editor').onsubmit=ev=>{ev.preventDefault();syncQuestions();const f=ev.currentTarget;if(Number(f.duration.value)<=0||Number(f.duration.value)>180||f.opens.value>=f.closes.value){$('#quiz-error').textContent=db.settings.language==='bn'?'সময় ১–১৮০ মিনিট এবং শেষ সময় শুরুর পরে দিন।':'Use 1–180 minutes and a closing time after the opening time.';return;}if(!questionDraft.length||questionDraft.some(q=>!q.text.trim()||q.options.some(x=>!x.trim()))){$('#quiz-error').textContent=t('Questions')+' · '+t('No records yet');return;}const r={id:original?.id||uid(),teacherId:session.teacherId,title:f.elements.title.value,subject:f.subject.value,batchId:f.batchId.value,duration:Number(f.duration.value),opens:f.opens.value,closes:f.closes.value,status:f.status.value,random:f.random.checked,questions:structuredClone(questionDraft)},before=original?structuredClone(original):null;if(original)Object.assign(original,r);else db.quizzes.push(r);save(original?'Edit':'Create','quizzes',r.id,before);closeModal();render();toast(t('Saved successfully'));};}
function renderQuestionEditors(){$('#question-editors').innerHTML=questionDraft.map((q,i)=>'<div class="question-editor"><div class="card-top"><strong style="font-size:12px">'+e('Question')+' '+num(i+1)+'</strong>'+btn('Remove','question-remove:'+i,'small danger')+'</div><div class="form-grid">'+field('qtext-'+i,'Question','textarea',q.text,[],true,true)+q.options.map((v,j)=>field('qopt-'+i+'-'+j,String.fromCharCode(65+j),'text',v,[],true)).join('')+field('qanswer-'+i,'Correct answer','select',q.answer,['A','B','C','D'].map((x,j)=>({value:j,label:x})),true)+field('qtopic-'+i,'Chapter','text',q.topic||'')+'</div></div>').join('');}
function syncQuestions(){questionDraft.forEach((q,i)=>{q.text=$('[name=qtext-'+i+']').value;q.options=q.options.map((_,j)=>$('[name=qopt-'+i+'-'+j+']').value);q.answer=Number($('[name=qanswer-'+i+']').value);q.topic=$('[name=qtopic-'+i+']').value;});}
function startQuiz(id){if(!isStudent())return;const quiz=visible('quizzes').find(q=>q.id===id);if(!quiz)return;const done=db.attempts.find(a=>a.studentId===session.id&&a.quizId===id);if(done){quizReview(id);return;}if(Date.now()<new Date(quiz.opens).getTime()||Date.now()>new Date(quiz.closes).getTime()){toast(db.settings.language==='bn'?'কুইজ এখন খোলা নেই।':'This quiz is not open right now.',true);return;}const key='sl-quiz-'+session.id+'-'+id;let draft=JSON.parse(localStorage.getItem(key)||'null');if(!draft){const order=quiz.questions.map(q=>q.id);if(quiz.random)for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}draft={end:Math.min(Date.now()+quiz.duration*60000,new Date(quiz.closes).getTime()),answers:{},order};localStorage.setItem(key,JSON.stringify(draft));}modal(quiz.title,'<div class="quiz-timer">'+e('Time remaining')+' <strong id="quiz-timer"></strong></div><div id="quiz-questions">'+draft.order.map((qid,i)=>{const q=quiz.questions.find(q=>q.id===qid);return '<section class="quiz-question"><h3>'+num(i+1)+'. '+esc(q.text)+'</h3>'+q.options.map((o,j)=>'<button class="quiz-option '+(draft.answers[q.id]===j?'selected':'')+'" data-q="'+q.id+'" data-answer="'+j+'"><span>'+String.fromCharCode(65+j)+'</span>'+esc(o)+'</button>').join('')+'</section>';}).join('')+'</div>','<button class="btn primary" id="finish-quiz">'+e('Submit quiz')+'</button>',true);$('dialog').dataset.quiz='true';$('dialog .modal-header [data-action=close]').hidden=true;$$('.quiz-option').forEach(b=>b.onclick=()=>{draft.answers[b.dataset.q]=Number(b.dataset.answer);localStorage.setItem(key,JSON.stringify(draft));$$('[data-q="'+b.dataset.q+'"]').forEach(x=>x.classList.toggle('selected',x===b));});let submitted=false;const finish=()=>{if(submitted)return;submitted=true;clearInterval(quizInterval);const correct=quiz.questions.filter(q=>draft.answers[q.id]===q.answer).length;db.attempts.push({id:uid(),teacherId:session.teacherId,studentId:session.id,quizId:id,answers:draft.answers,score:correct,total:quiz.questions.length,submittedAt:new Date().toISOString()});save('Submit','attempts',id);localStorage.removeItem(key);delete $('dialog').dataset.quiz;closeModal();render();quizReview(id);};$('#finish-quiz').onclick=finish;const tick=()=>{const remaining=Math.max(0,Math.ceil((draft.end-Date.now())/1000));if($('#quiz-timer'))$('#quiz-timer').textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(!remaining)finish();};tick();if(!submitted)quizInterval=setInterval(tick,1000);}
function quizReview(id){const quiz=visible('quizzes').find(q=>q.id===id),attempt=visible('attempts').find(a=>a.quizId===id);if(!quiz||!attempt)return;modal('Review answers','<div class="hint"><strong>'+e('Your score')+': '+num(attempt.score)+' / '+num(attempt.total)+'</strong> · '+date(attempt.submittedAt)+'</div>'+quiz.questions.map((q,i)=>'<section class="quiz-question"><h3>'+num(i+1)+'. '+esc(q.text)+'</h3>'+q.options.map((o,j)=>'<div class="quiz-option '+(j===q.answer?'correct':attempt.answers[q.id]===j?'wrong':'')+'"><span>'+String.fromCharCode(65+j)+'</span>'+esc(o)+(j===q.answer?' ✓':'')+(attempt.answers[q.id]===j?' · '+e('You'):'')+'</div>').join('')+'</section>').join(''),btn('Close','close'),true);}
function quizAnalytics(id){if(isStudent())return;const quiz=own('quizzes').find(q=>q.id===id);if(!quiz)return;const attempts=own('attempts').filter(a=>a.quizId===id);modal('Analytics','<p class="hint">'+num(attempts.length)+' '+e('Submitted')+' · '+e('Average')+': '+(attempts.length?num(Math.round(attempts.reduce((s,a)=>s+a.score/a.total*100,0)/attempts.length))+'%':'—')+'</p>'+quiz.questions.map(q=>{const wrong=attempts.filter(a=>a.answers[q.id]!==q.answer).length;return '<div class="switch-row"><span>'+esc(q.text)+'<p>'+esc(q.topic)+'</p></span><span class="badge '+(wrong?'amber':'green')+'">'+num(wrong)+' / '+num(attempts.length)+' '+(db.settings.language==='bn'?'ভুল':'incorrect')+'</span></div>';}).join('')+'<h3 class="section-gap" style="font-size:14px">'+e('Student progress')+'</h3>'+attempts.sort((a,b)=>b.score-a.score).map(a=>'<div class="switch-row"><span>'+esc(studentName(a.studentId))+'</span><b>'+a.score+'/'+a.total+'</b></div>').join(''),btn('Close','close'),true);}
function routinePage(){return heading('Routine',t('Your week, at a glance.'),canManage()?btn('Add class','create:routine','primary','plus'):'')+'<div class="cards">'+[6,0,1,2,3,4,5].map(day=>'<section class="panel"><div class="panel-header"><h2>'+esc(dayName(day))+'</h2>'+(day===new Date().getDay()?badge('Today'):'')+'</div><div class="panel-body">'+(visible('routine').filter(r=>Number(r.day)===day).sort((a,b)=>a.start.localeCompare(b.start)).map(r=>'<div class="schedule-row"><span class="subject-symbol">'+icon('routine')+'</span><div class="row-main"><strong>'+esc(r.subject)+'</strong><small>'+esc(time(r.start))+' – '+esc(time(r.end))+'</small><small>'+esc(batchName(r.batchId))+' · '+esc(r.room)+'</small><div class="actions" style="margin-top:10px">'+(safeURL(r.url)?'<a href="'+esc(safeURL(r.url))+'" target="_blank" rel="noopener noreferrer" class="btn small">'+e('Open')+' ↗</a>':'')+(canManage()?recordActions('routine',r):'')+'</div></div></div>').join('')||'<div class="empty" style="padding:25px">—</div>')+'</div></section>').join('')+'</div>';}
function feesPage(){const people=isStudent()?[me()]:students(),due=people.reduce((s,p)=>s+outstanding(db,p.id,feeMonth),0),payments=visible('payments').filter(p=>p.month===feeMonth),collected=payments.reduce((s,p)=>s+p.amount,0);return heading('Fees',t('Verified manually'),'<input id="fee-month" type="month" value="'+feeMonth+'" aria-label="'+e('Month')+'">'+(canManage()?btn('Record payment','create:payments','primary','plus'):''))+'<div class="stats">'+stat('Collection this month',money(collected),feeMonth,'fees')+stat('Outstanding fees',money(due),feeMonth,'clock')+stat('Paid',num(payments.length),t('Payment history'),'check')+stat('Due',num(people.filter(s=>outstanding(db,s.id,feeMonth)>0).length),t('Students'),'students')+'</div><div class="tabs">'+['Due list','Payment history'].map((x,i)=>'<button class="tab '+((tab||'due')===(i?'history':'due')?'active':'')+'" data-action="fee-tab:'+(i?'history':'due')+'">'+e(x)+'</button>').join('')+'</div><section class="panel">'+((tab||'due')==='due'?'<div class="table-wrap"><table><thead><tr>'+['Student','Batch','Monthly fee','Due','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+people.map(s=>{const amount=outstanding(db,s.id,feeMonth);return '<tr><td><div class="person">'+avatar(s.name)+esc(s.name)+'</div></td><td>'+s.batchIds.map(id=>esc(batchName(id))).join('<br>')+'</td><td>'+money(s.batchIds.reduce((sum,id)=>sum+Number(db.batches.find(b=>b.id===id&&b.status==='Active')?.fee||0),0))+'</td><td>'+(amount?'<span style="color:var(--amber)">'+money(amount)+'</span>':badge('Paid'))+'</td><td>'+(canManage()&&amount?btn('Record payment','pay-for:'+s.id,'small'):'—')+'</td></tr>';}).join('')+'</tbody></table></div>':'<div class="toolbar">'+btn('Export CSV','export:payments','','download')+'</div><div class="table-wrap"><table><thead><tr>'+['Student','Date','Batch','Amount','Method','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+payments.map(p=>'<tr><td>'+esc(studentName(p.studentId))+'</td><td>'+date(p.date)+'</td><td>'+esc(batchName(p.batchId))+'</td><td>'+money(p.amount)+'</td><td>'+esc(p.method)+'</td><td>'+recordActions('payments',p,btn('Receipt','receipt:'+p.id,'small'))+'</td></tr>').join('')+'</tbody></table></div>')+'</section>';}
function receipt(id){const p=visible('payments').find(p=>p.id===id);if(!p)return;modal('Receipt','<div class="report"><div class="card-top"><h1>'+esc(teacher().coaching)+'</h1>'+badge('Paid')+'</div><p style="margin-top:12px">'+e('Receipt')+' #'+esc(p.id.slice(0,8))+'</p><hr style="margin:25px 0;border:0;border-top:1px solid #ddd"><dl class="summary-list">'+[['Student',studentName(p.studentId)],['Batch',batchName(p.batchId)],['Month',p.month],['Date',date(p.date)],['Method',p.method],['Reference',p.reference||'—']].map(([k,v])=>'<div><dt>'+e(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><div style="padding:22px 0;border-top:1px solid #ddd;font-size:24px">'+e('Amount')+': '+money(p.amount)+'</div><p>'+e('Verified manually')+'</p></div>',btn('Print report','print','','download')+btn('Close','close'));}
function calendarEvents(day){return [...visible('exams').filter(x=>x.date===day).map(x=>({title:x.title,kind:'exam',action:'exam:'+x.id})),...visible('assignments').filter(x=>x.deadline.slice(0,10)===day).map(x=>({title:x.title,kind:'assignment',action:'assignment:'+x.id})),...visible('routine').filter(x=>Number(x.day)===new Date(day+'T12:00').getDay()).map(x=>({title:time(x.start)+' · '+x.subject,kind:'class',action:'detail:routine:'+x.id})),...visible('events').filter(x=>x.date===day).map(x=>({title:x.title,kind:'event',action:'detail:events:'+x.id}))];}
function calendarPage(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),count=new Date(y,m+1,0).getDate(),first=new Date(y,m,1).getDay();return heading('Calendar',calendarDate.toLocaleDateString(db.settings.language==='bn'?'bn-BD':'en',{month:'long',year:'numeric'}),btn('Previous','calendar-prev','small')+btn('Today','calendar-today','small')+btn('Next','calendar-next','small')+(canManage()?btn('Create','create:events','primary','plus'):''))+'<div class="tabs">'+['month','week','list'].map(mode=>'<button class="tab '+(calendarMode===mode?'active':'')+'" data-action="calendar-mode:'+mode+'">'+e(mode==='month'?'Month':mode==='week'?'Week':'List')+'</button>').join('')+'</div><section class="panel">'+(calendarMode==='list'?Array.from({length:count},(_,i)=>{const d=y+'-'+String(m+1).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'),events=calendarEvents(d);return events.length?'<div class="switch-row" style="padding:18px 22px"><span>'+date(d)+'</span><div>'+events.map(v=>'<button class="calendar-event '+v.kind+'" data-action="'+v.action+'">'+esc(v.title)+'</button>').join('')+'</div></div>':'';}).join(''):'<div class="calendar-grid">'+weekdays.map((_,i)=>'<div class="calendar-weekday">'+esc(dayName(i))+'</div>').join('')+(calendarMode==='month'?'<div class="calendar-day"></div>'.repeat(first):'')+Array.from({length:calendarMode==='week'?7:count},(_,i)=>{const n=calendarMode==='week'?Math.max(1,Math.min(count-6,calendarDate.getDate()-calendarDate.getDay()))+i:i+1,d=y+'-'+String(m+1).padStart(2,'0')+'-'+String(n).padStart(2,'0');return '<div class="calendar-day '+(d===today()?'today':'')+'"><span>'+num(n)+'</span>'+calendarEvents(d).map(v=>'<button class="calendar-event '+v.kind+'" data-action="'+v.action+'" title="'+esc(v.title)+'">'+esc(v.title)+'</button>').join('')+'</div>';}).join('')+'</div>')+'</section>';}
function messagesPage(){const contacts=(isStudent()?[{id:session.id,name:teacher().name}]:students()).concat(batches().filter(b=>!isStudent()||me().batchIds.includes(b.id)).map(b=>({id:'group-'+b.id,name:b.name,group:true})));if(!contacts.some(s=>s.id===chatStudent))chatStudent=contacts[0]?.id||'';const group=chatStudent.startsWith('group-'),groupBatch=group?batches().find(b=>b.id===chatStudent.slice(6)):null,canSend=!group||!isStudent()||!!groupBatch?.discussion,messages=visible('messages').filter(m=>group?m.group&&m.batchId===groupBatch?.id:!m.group&&m.studentId===chatStudent);return heading('Messages',t('Local delivery'))+'<section class="panel chat-layout"><div class="chat-list">'+contacts.map((s,i)=>'<button class="conversation '+(s.id===chatStudent?'active':'')+'" data-action="chat:'+s.id+'">'+avatar(s.name,i)+'<div class="row-main"><strong>'+esc(s.name)+'</strong><small>'+e(s.group?'Batch group':isStudent()?'Teacher':'Student')+'</small></div></button>').join('')+'</div><div class="chat-main">'+(chatStudent?'<div class="chat-head"><div class="person">'+avatar(recipientName(chatStudent))+'<div class="row-main"><strong>'+esc(recipientName(chatStudent))+'</strong><small>'+e(group?(groupBatch?.discussion?'Open discussion':'Teacher announcements'):'Local delivery')+'</small></div>'+(group&&!isStudent()?btn(groupBatch.discussion?'Teacher announcements':'Open discussion','group-mode:'+groupBatch.id,'small'):'')+'</div></div><div class="chat-feed" id="chat-feed">'+(messages.map(m=>'<div class="bubble '+(m.sender===session.id?'mine':'')+'">'+(group?'<small style="color:var(--accent)">'+esc(db.students.find(s=>s.id===m.sender)?.name||db.teachers.find(t=>t.id===m.sender)?.name||t('Teacher'))+'</small>':'')+'<div>'+esc(m.text)+'</div>'+filesHTML(m.files)+'<small>'+new Date(m.created).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+' · '+e(m.read?'Read':'Local delivery')+(m.sender===session.id&&Date.now()-new Date(m.created).getTime()<900000?' <button class="text-link" data-action="message-edit:'+m.id+'">'+e('Edit')+'</button><button class="text-link" data-action="message-delete:'+m.id+'">'+e('Delete')+'</button>':'')+'</small></div>').join('')||'<div class="empty">'+e('No messages yet')+'</div>')+'</div>'+(canSend?'<form id="chat-form" class="chat-compose"><input name="message" type="text" placeholder="'+e('Write a message…')+'" aria-label="'+e('Messages')+'"><label class="icon-button" title="'+e('Attachment')+'" style="cursor:pointer">'+icon('file')+'<input type="file" name="attachment" style="position:absolute;inset:0;opacity:0;cursor:pointer" aria-label="'+e('Attachment')+'"></label><button type="submit" class="btn primary">'+icon('arrow')+'<span>'+e('Send')+'</span></button></form>':'<div class="hint" style="margin:15px">'+e('Only your teacher can post here.')+'</div>'):'<div class="empty">'+e('Select a conversation')+'</div>')+'</div></section>';}

function analyticsPage(){const people=filtered(students());return heading('Analytics',t('Student progress'),btn('Export CSV','export:analytics','','download'))+'<div class="split">'+panel('Learning pulse',pulse())+panel('Attendance vs performance',people.slice(0,6).map(s=>{const marks=own('marks').filter(m=>m.studentId===s.id),avg=marks.length?Math.round(marks.reduce((n,m)=>n+m.marks/(db.exams.find(e=>e.id===m.examId)?.total||100)*100,0)/marks.length):0;return '<div class="bar-row"><span>'+esc(s.name.split(' ')[0])+'</span><div><div class="progress"><span style="width:'+avg+'%"></span></div><div class="progress" style="margin-top:5px"><span style="width:'+attendanceRate(own('attendance').filter(a=>a.studentId===s.id))+'%;background:var(--purple)"></span></div></div><span>'+num(avg)+'%</span></div>';}).join('')+'<div class="chart-legend"><span><i></i>'+e('Marks')+'</span><span><i style="background:var(--purple)"></i>'+e('Attendance')+'</span></div>')+'</div><section class="panel section-gap">'+toolbar(true)+'<div class="table-wrap"><table><thead><tr>'+['Student','Attendance','Average','Pending','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+people.map(s=>{const marks=own('marks').filter(m=>m.studentId===s.id),average=marks.length?Math.round(marks.reduce((sum,m)=>sum+m.marks/(db.exams.find(e=>e.id===m.examId)?.total||100)*100,0)/marks.length):0,pending=own('assignments').filter(a=>a.status==='Published'&&s.batchIds.includes(a.batchId)&&!db.submissions.some(m=>m.assignmentId===a.id&&m.studentId===s.id)).length;return '<tr><td>'+esc(s.name)+'</td><td>'+attendanceRate(own('attendance').filter(a=>a.studentId===s.id))+'%</td><td>'+average+'%</td><td>'+pending+'</td><td>'+btn('Student progress','profile:'+s.id,'small')+'</td></tr>';}).join('')+'</tbody></table></div></section>';}

function adminDashboard(){const active=db.teachers.filter(t=>t.status==='Active').length,total=db.students.filter(s=>s.status==='Active').length,paid=db.billing.filter(b=>b.month===month()).reduce((n,b)=>n+b.amount,0);return heading('Platform overview',t('A clear view of every classroom.'),btn('Create teacher','create:teachers','primary','plus'))+'<div class="stats">'+stat('Teachers',num(db.teachers.length),t('Total'),'teachers')+stat('Active',num(active),t('Teachers'),'check')+stat('Students',num(total),t('Students enrolled'),'students')+stat('Collection this month',money(paid),month(),'billing')+'</div><div class="split">'+panel('Teachers',db.teachers.map((r,i)=>'<div class="switch-row"><div class="person">'+avatar(r.name,i)+'<div>'+esc(r.name)+'<p>'+esc(r.coaching)+' · '+esc(db.plans.find(p=>p.id===r.plan)?.name||r.plan)+'</p></div></div>'+badge(r.status)+'</div>').join(''),'<button class="text-link" data-go="teachers">'+e('View all')+' ↗</button>')+panel('Usage & monitoring',db.teachers.map(r=>{const count=db.students.filter(s=>s.teacherId===r.id&&s.status==='Active').length;return '<div style="margin:15px 0 24px"><div class="card-top" style="font-size:12px;margin-bottom:10px"><span>'+esc(r.coaching)+'</span><span class="text-muted">'+count+'/'+r.studentLimit+' '+e('Students')+'</span></div><div class="progress"><span style="width:'+Math.min(100,count/r.studentLimit*100)+'%"></span></div></div>';}).join('')+'<p class="hint">'+e('No API connected')+' · AI: 0</p>')+'</div>'+panel('Recent activity',db.audit.slice(0,6).map(a=>'<div class="switch-row"><span>'+esc(a.actor)+'<p>'+e(a.action)+' · '+e(labels[a.entity]||a.entity)+'</p></span><span class="text-muted">'+date(a.created)+'</span></div>').join('')||empty(),'', 'section-gap');}
function teachersPage(){const rows=filtered(db.teachers);return heading('Teachers',t('Platform overview'),btn('Create teacher','create:teachers','primary','plus'))+'<section class="panel">'+toolbar(false)+'<div class="table-wrap"><table><thead><tr>'+['Teacher','Plan','Subscription expiry','Students','Status','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map((r,i)=>'<tr><td><div class="person">'+avatar(r.name,i)+'<div>'+esc(r.name)+'<small>'+esc(r.email)+'<br>'+esc(r.coaching)+'</small></div></div></td><td>'+esc(db.plans.find(p=>p.id===r.plan)?.name||r.plan)+'</td><td>'+date(r.expiry)+'</td><td>'+db.students.filter(s=>s.teacherId===r.id).length+'/'+r.studentLimit+'</td><td>'+badge(r.status)+'</td><td><div class="actions">'+btn('Features','features:'+r.id,'small')+btn(r.status==='Suspended'?'Activate':'Suspend','suspend:'+r.id,'small')+btn('View as teacher','impersonate:'+r.id,'small')+recordActions('teachers',r)+'</div></td></tr>').join('')+'</tbody></table></div></section>';}
function teacherFeatures(id){if(!isAdmin())return;const r=db.teachers.find(x=>x.id===id);if(!r)return;modal('Features','<p class="subtitle">'+esc(r.name)+'</p><form id="features-form">'+Object.entries({messages:'Messages',materials:'Materials',quizzes:'Quizzes',ai:'AI Studio',fees:'Fees',guardians:'Guardians'}).map(([key,label])=>'<label class="switch-row"><span>'+e(label)+'</span><input class="switch" type="checkbox" name="'+key+'" '+(r.features[key]?'checked':'')+'></label>').join('')+'<div class="form-grid section-gap">'+field('studentLimit','Student limit','number',r.studentLimit,[],true)+field('batchLimit','Batch limit','number',r.batchLimit,[],true)+field('storageLimit','Storage limit (MB)','number',r.storageLimit,[],true)+'</div><button class="btn primary section-gap" type="submit">'+e('Save changes')+'</button></form>');$('#features-form').onsubmit=ev=>{ev.preventDefault();const before=structuredClone(r),f=ev.currentTarget;for(const key of Object.keys(r.features))r.features[key]=f.elements[key].checked;for(const key of ['studentLimit','batchLimit','storageLimit'])r[key]=Number(f.elements[key].value);save('Edit','teachers',id,before);closeModal();render();toast(t('Saved successfully'));};}
function plansPage(){return heading('Plans',t('Platform overview'),btn('Create plan','create:plans','primary','plus'))+'<div class="cards">'+db.plans.map((p,i)=>'<article class="card" '+(i===2?'style="border-color:var(--accent)"':'')+'><div class="card-top"><span class="subject-symbol">'+icon('plans')+'</span>'+badge(i===2?'Pro':'Plan')+'</div><h3>'+esc(p.name)+'</h3><div style="font-size:32px;margin:22px 0">'+money(p.price)+'<span class="text-muted" style="font-size:11px"> / '+e('Month')+'</span></div>'+[['Student limit',p.studentLimit],['Batch limit',p.batchLimit],['Storage limit (MB)',p.storageLimit]].map(([k,v])=>'<div class="switch-row"><span>'+e(k)+'</span><strong>'+num(v)+'</strong></div>').join('')+'<div class="card-bottom">'+recordActions('plans',p)+'</div></article>').join('')+'</div>';}
function billingPage(){return heading('Billing',t('Verified manually'),btn('Record payment','create:billing','primary','plus'))+'<section class="panel"><div class="table-wrap"><table><thead><tr>'+['Teacher','Month','Amount','Method','Reference','Date','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+db.billing.map(b=>'<tr><td>'+esc(db.teachers.find(t=>t.id===b.teacherId)?.name||'—')+'</td><td>'+b.month+'</td><td>'+money(b.amount)+'</td><td>'+esc(b.method)+'</td><td>'+esc(b.reference)+'</td><td>'+date(b.date)+'</td><td>'+recordActions('billing',b)+'</td></tr>').join('')+'</tbody></table></div>'+(db.billing.length?'':empty())+'</section>';}
function auditPage(){return heading('Audit log',t('Activity'),btn('Export CSV','export:audit','','download'))+'<section class="panel">'+toolbar(false)+'<div class="table-wrap"><table><thead><tr>'+['Actor','Action','Record','Time','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+db.audit.filter(a=>!filter||[a.actor,a.entity,a.action].join(' ').toLowerCase().includes(filter.toLowerCase())).slice(0,200).map(a=>'<tr><td>'+esc(a.actor)+'</td><td>'+badge(a.action)+'</td><td>'+e(labels[a.entity]||a.entity)+'</td><td>'+new Date(a.created).toLocaleString(db.settings.language==='bn'?'bn-BD':'en-GB')+'</td><td>'+btn('Open','audit-detail:'+a.id,'small')+'</td></tr>').join('')+'</tbody></table></div>'+(db.audit.length?'':empty())+'</section>';}
function guardiansPage(){const q=own('queue');return heading('Guardians',t('Notification queue'),btn('Generate preview','guardian-refresh','','Refresh'))+'<div class="hint">'+(db.settings.language==='bn'?'মেসেজগুলো স্থানীয় প্রিভিউ। API যুক্ত না হওয়া পর্যন্ত স্বয়ংক্রিয়ভাবে পাঠানো হবে না।':'Messages are local previews. Automatic delivery becomes available after connecting an API.')+'</div><section class="panel"><div class="table-wrap"><table><thead><tr>'+['Student','Guardian WhatsApp','Category','Time','Status','Actions'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+q.map(r=>'<tr><td>'+esc(studentName(r.studentId))+'</td><td>'+esc(db.students.find(s=>s.id===r.studentId)?.guardianPhone||'—')+'</td><td>'+e(r.type)+'</td><td>'+date(r.created)+'</td><td>'+badge(r.status)+'</td><td>'+btn('Preview message','queue:'+r.id,'small')+'</td></tr>').join('')+'</tbody></table></div>'+(q.length?'':empty())+'</section>';}
function aiPage(){return heading('AI Studio',t('Local previews'),badge('No API connected'))+'<div class="hint">'+(db.settings.language==='bn'?'API পরে যুক্ত হবে। এখানে নমুনা কুইজ ও আপনার স্থানীয় তথ্য থেকে নিয়মভিত্তিক বিশ্লেষণ দেখা যাবে। এগুলো AI তৈরি ফলাফল নয়।':'Connect an AI provider later. These previews use sample quiz content and rule-based analysis of your local records; they are not AI-generated results.')+'</div><div class="cards">'+[['Quiz assistant','quizzes','A practice set to start a conversation.','অনুশীলনের জন্য একটি নমুনা কুইজ।'],['Grading assistant','assignments','A review checklist for thoughtful feedback.','মতামতের আগে মূল্যায়নের চেকলিস্ট।'],['Learning insights','analytics','Spot attendance and learning gaps.','হাজিরা ও শেখার ঘাটতি দেখুন।'],['Guardian assistant','guardians','Preview a clear student summary.','শিক্ষার্থীর সারাংশ দেখুন।']].map(([name,ico,en,bn])=>'<article class="card"><span class="subject-symbol">'+icon(ico)+'</span><h3>'+e(name)+'</h3><p>'+esc(db.settings.language==='bn'?bn:en)+'</p><div class="card-bottom">'+btn('Generate preview','ai-preview:'+ico,'small primary','ai')+'</div></article>').join('')+'</div>';}
function aiPreview(type){let content='';if(type==='quizzes')content=db.quizzes[0]?.questions.map((q,i)=>'<div class="quiz-question"><h3>'+num(i+1)+'. '+esc(q.text)+'</h3><p class="detail-text">'+q.options.map((o,j)=>String.fromCharCode(65+j)+'. '+esc(o)).join('<br>')+'</p></div>').join('')||empty();if(type==='assignments')content='<p class="detail-text">'+(db.settings.language==='bn'?'১. ধারণার যথার্থতা যাচাই করুন।\n২. ব্যবহৃত সূত্র ও একক পরীক্ষা করুন।\n৩. সমাধানের ধাপগুলো মূল্যায়ন করুন।\n৪. নিজে নম্বর ও গঠনমূলক মতামত দিন।':'1. Check conceptual accuracy.\n2. Verify formulas and units.\n3. Evaluate the reasoning steps.\n4. Assign marks and actionable feedback yourself.')+'</p>';if(type==='analytics')content=students().map(s=>{const rate=attendanceRate(own('attendance').filter(a=>a.studentId===s.id));const misses=own('assignments').filter(a=>a.status==='Published'&&s.batchIds.includes(a.batchId)&&!db.submissions.some(x=>x.studentId===s.id&&x.assignmentId===a.id)).length;return '<div class="switch-row"><span>'+esc(s.name)+'<p>'+e('Attendance')+': '+rate+'% · '+e('Pending')+': '+misses+'</p></span>'+badge(rate<85||misses>1?'Pending':'Active')+'</div>';}).join('');if(type==='guardians'){const s=students()[0];content=s?'<p class="detail-text">'+esc(guardianSummary(s))+'</p>':empty();}modal('Local previews','<p class="hint warning">'+e('Review before use')+' · '+e('No API connected')+'</p>'+content,btn('Close','close'),true);}
function guardianSummary(s){return db.settings.language==='bn'?s.name+' — '+date(today())+'\nহাজিরা: '+attendanceRate(own('attendance').filter(a=>a.studentId===s.id))+'%\nবকেয়া ফি: '+money(outstanding(db,s.id))+'\nকোনো প্রশ্ন থাকলে শিক্ষকের সাথে যোগাযোগ করুন।':s.name+' — '+date(today())+'\nAttendance: '+attendanceRate(own('attendance').filter(a=>a.studentId===s.id))+'%\nOutstanding fee: '+money(outstanding(db,s.id))+'\nPlease contact your teacher with any questions.';}
function settingsPage(){const tabs={general:'General',appearance:'Appearance',notifications:'Notifications',security:'Security',data:'Data & backup'};const pref=db.preferences[currentUser()]||{};let body='';if(settingsTab==='general')body='<form id="settings-general"><div class="form-grid">'+field('name','Display name','text',isAdmin()?'Super Admin':me()?.name||'',[],true)+(!isStudent()?field('coaching','Coaching name','text',teacher()?.coaching||db.settings.coaching,[],true):field('phone','Phone','tel',me()?.phone||''))+field('language','Language','select',db.settings.language,[{value:'en',label:'English'},{value:'bn',label:'বাংলা'}],true)+(isAdmin()?field('uploadLimit','Maximum upload (MB)','number',db.settings.uploadLimit,[],true)+field('extensions','Allowed extensions','text',db.settings.extensions,[],true,true)+field('grace','Grace period (days)','number',db.settings.grace,[],true):!isStudent()?field('grading','Grading scale','text',db.settings.grading,[],true,true):'')+'</div><div class="error" id="settings-error"></div><button class="btn primary" type="submit">'+e('Save changes')+'</button></form>';
if(settingsTab==='appearance')body='<form id="appearance-form"><div class="form-grid">'+field('theme','Theme','select',db.settings.theme,[{value:'dark',label:t('Dark')},{value:'light',label:t('Light')}])+'</div><label class="switch-row"><span>'+e('Reduced motion')+'<p>150–250 ms · '+(db.settings.language==='bn'?'ব্রাউজারের পছন্দও প্রযোজ্য':'Browser preferences are also respected')+'</p></span><input class="switch" name="reduced" type="checkbox" '+(!db.settings.motion?'checked':'')+'></label><button class="btn primary section-gap" type="submit">'+e('Save changes')+'</button></form>';
if(settingsTab==='notifications')body='<form id="notifications-form"><label class="switch-row"><span>'+e('Critical reminders')+'<p>'+e('Assignments')+' · '+e('Exams')+'</p></span><input class="switch" type="checkbox" checked disabled aria-label="'+e('Critical reminders')+'"></label>'+['messages','notices','fees','attendance'].map(k=>'<label class="switch-row"><span>'+e(labels[k])+'</span><input type="checkbox" class="switch" name="'+k+'" '+(pref[k]!==false?'checked':'')+'></label>').join('')+'<button type="submit" class="btn primary section-gap">'+e('Save changes')+'</button></form>';
if(settingsTab==='security')body='<p class="hint">'+(db.settings.language==='bn'?'এটি স্থানীয় ডেমো। আসল অ্যাকাউন্ট নিরাপত্তা ও ডেটা বিচ্ছিন্নতা ব্যাকএন্ড যুক্ত করার পর চালু হবে।':'This is a local demo. Production account security and data isolation require the future backend.')+'</p>'+(!session.demo?'<form id="password-form"><div class="form-grid">'+field('current','Current password','password','',[],true,true)+field('password','New password','password','',[],true,true)+'</div><div id="password-error" class="error"></div><button type="submit" class="btn primary">'+e('Change password')+'</button></form>':'<p class="detail-text">'+(db.settings.language==='bn'?'ডেমো প্রবেশে পাসওয়ার্ড নেই। অ্যাডমিন/শিক্ষক তৈরি করা অ্যাকাউন্টে পাসওয়ার্ড পরিবর্তন করা যাবে।':'Demo access has no password. Accounts created by an administrator or teacher can change their password here.')+'</p>')+btn('Sign out','logout','section-gap','logout');
if(settingsTab==='data')body='<p class="hint">'+(db.settings.language==='bn'?'ব্যাকআপে আপনার অনুমোদিত রেকর্ড ও সংযুক্ত ফাইল থাকবে। আমদানি করলে সংশ্লিষ্ট স্থানীয় তথ্য প্রতিস্থাপিত হবে।':'Backups include the records and attachments available to your role. Import replaces the corresponding local records.')+'</p><div class="actions">'+btn('Export backup','backup-export','primary','download')+(!isStudent()?'<label class="btn">'+icon('file')+e('Import backup')+'<input id="backup-import" type="file" accept=".json" hidden></label>':'')+'</div><div class="section-gap">'+btn('Export CSV','export:students','','download')+'</div>';
return heading('Settings',t('Preferences'))+'<div class="settings-layout"><nav class="settings-nav">'+Object.entries(tabs).map(([key,label])=>'<button class="tab '+(settingsTab===key?'active':'')+'" data-action="settings-tab:'+key+'">'+e(label)+'</button>').join('')+'</nav><section class="panel settings-panel"><h2>'+e(tabs[settingsTab])+'</h2>'+body+'</section></div>';}
function renderLogin(){$('#app').innerHTML='<main class="login"><section class="login-story"><div class="brand"><img src="favicon.svg" alt=""><div><strong>Science Lab.</strong><small>Coaching workspace</small></div></div><div><div class="eyebrow">LEARN · EXPERIMENT · GROW</div><h1>'+e('Your next discovery starts here.')+'</h1><p>'+e('A little structure. A lot of possibility.')+'</p><div class="lab-art"><i class="orbit"></i><i class="orbit two"></i><i class="orbit three"></i><img src="favicon.svg" alt=""></div></div><p style="font-size:11px">'+e('Local workspace')+' · '+e('Data stays in this browser')+'</p></section><section class="login-form"><div class="login-box"><div class="eyebrow">SCIENCE LAB</div><h2>'+e('Welcome to your lab.')+'</h2><p class="subtitle">'+e('Accounts are created by your administrator.')+'</p><form id="login-form">'+field('username','Username','text','',[],true)+field('password','Password','password','',[],true)+'<div id="login-error" class="error"></div><button type="submit" class="btn primary">'+e('Log in')+' '+icon('arrow')+'</button></form><div style="text-align:center;color:var(--muted);font-size:11px;margin-top:28px">'+e('Use a demo workspace')+'</div><div class="demo-roles">'+btn('Teacher','demo:teacher')+btn('Student','demo:student')+btn('Super Admin','demo:admin')+'</div><button class="btn ghost" data-action="language">'+(db.settings.language==='en'?'বাংলায় দেখুন':'Switch to English')+'</button></div></section></main>';$('#login-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,a=db.accounts.find(a=>a.username.toLowerCase()===f.username.value.trim().toLowerCase());if(!a||await passwordHash(f.password.value,a.salt)!==a.hash){$('#login-error').textContent=db.settings.language==='bn'?'ইউজারনেম বা পাসওয়ার্ড ভুল।':'Incorrect username or password.';return;}const teacher=db.teachers.find(t=>t.id===a.teacherId),student=db.students.find(s=>s.id===a.ref);if(!teacher||teacher.status==='Suspended'||a.role==='student'&&student?.status!=='Active'){$('#login-error').textContent=db.settings.language==='bn'?'অ্যাকাউন্টটি নিষ্ক্রিয়।':'This account is inactive.';return;}if(a.forceReset){forcePasswordReset(a);return;}setSession({role:a.role,id:a.ref,teacherId:a.teacherId,accountId:a.id,demo:false});save('Log in','accounts',a.id);};}
function setSession(s){session=s;sessionStorage.setItem('sl-session',JSON.stringify(s));page='dashboard';location.hash='dashboard';filter='';batchFilter='all';statusFilter='all';chatStudent='';attBatch='';render();}
function forcePasswordReset(a){modal('Change password','<p class="hint">'+(db.settings.language==='bn'?'চালিয়ে যেতে নতুন পাসওয়ার্ড দিন (কমপক্ষে ৮ অক্ষর)।':'Choose a new password to continue (at least 8 characters).')+'</p><form id="force-password">'+field('password','New password','password','',[],true,true)+'<div class="error" id="force-error"></div><button type="submit" class="btn primary section-gap">'+e('Save')+'</button></form>');$('#force-password').onsubmit=async ev=>{ev.preventDefault();const password=ev.currentTarget.password.value;if(password.length<8||await passwordHash(password,a.salt)===a.hash){$('#force-error').textContent=db.settings.language==='bn'?'নতুন এবং কমপক্ষে ৮ অক্ষরের পাসওয়ার্ড দিন।':'Use a different password of at least 8 characters.';return;}a.hash=await passwordHash(password,a.salt);a.forceReset=false;persist(db);closeModal();setSession({role:a.role,id:a.ref,teacherId:a.teacherId,accountId:a.id,demo:false});save('Change password','accounts',a.id);};}
function switchWorkspace(){modal('Switch workspace','<p class="hint">'+e('Demo access')+' · '+e('Local workspace')+'</p><div class="demo-roles">'+btn('Teacher','demo:teacher')+btn('Student','demo:student')+btn('Super Admin','demo:admin')+'</div><div class="form-grid section-gap">'+field('demoTeacher','Teacher','select',session.teacherId||'t1',db.teachers.map(x=>({value:x.id,label:x.name})))+field('demoStudent','Student','select','s1',db.students.filter(s=>s.status==='Active').map(x=>({value:x.id,label:x.name})))+'</div>',btn('Log in','logout')+btn('Close','close'));}

function bindFeatures(){
if($('#list-search'))$('#list-search').oninput=ev=>{const pos=ev.target.selectionStart;filter=ev.target.value;render();$('#list-search')?.focus();$('#list-search')?.setSelectionRange(pos,pos);};
if($('#batch-filter'))$('#batch-filter').onchange=ev=>{batchFilter=ev.target.value;render();};
if($('#status-filter'))$('#status-filter').onchange=ev=>{statusFilter=ev.target.value;render();};
if($('#att-date'))$('#att-date').onchange=ev=>{if(ev.target.value){attDate=ev.target.value;render();}};
if($('#att-batch'))$('#att-batch').onchange=ev=>{attBatch=ev.target.value;render();};
if($('#fee-month'))$('#fee-month').onchange=ev=>{if(ev.target.value){feeMonth=ev.target.value;render();}};
if($('#chat-feed'))$('#chat-feed').scrollTop=$('#chat-feed').scrollHeight;
if(page==='messages'&&chatStudent){let changed=false;own('messages').filter(m=>(chatStudent.startsWith('group-')?m.group&&m.batchId===chatStudent.slice(6):!m.group&&m.studentId===chatStudent)&&m.sender!==session.id&&!m.read).forEach(m=>{m.read=true;changed=true;});if(changed)persist(db);}
if($('#chat-form'))$('#chat-form').insertAdjacentHTML('beforeend',btn('Record voice','voice:attachment','small','clock'));
if($('#chat-form'))$('#chat-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget;try{const text=f.message.value.trim(),files=await uploadFiles(f.attachment,[]);if(!text&&!files.length)return;const group=chatStudent.startsWith('group-'),batch=group?batches().find(b=>b.id===chatStudent.slice(6)):null;if(group&&(!batch||isStudent()&&(!me().batchIds.includes(batch.id)||!batch.discussion)))return;const r={id:uid(),teacherId:session.teacherId,studentId:group?null:chatStudent,batchId:batch?.id||null,group,sender:session.id,text,files,created:new Date().toISOString(),read:false};db.messages.push(r);save('Create','messages',r.id);render();}catch(err){toast(err.message,true);}};
if($('#settings-general'))$('#settings-general').onsubmit=ev=>{ev.preventDefault();const f=ev.currentTarget;try{if(f.grading&&!/^(\d{1,3}:[A-Za-z][A-Za-z+-]*)(,\d{1,3}:[A-Za-z][A-Za-z+-]*)*$/.test(f.grading.value))throw Error('Use a scale such as 80:A+,70:A,60:A-,50:B,40:C,33:D,0:F');if(f.uploadLimit&&(Number(f.uploadLimit.value)<=0||Number(f.uploadLimit.value)>100))throw Error('Upload limit: 1–100 MB');if(!isAdmin())me().name=f.elements.name.value.trim();if(!isStudent()&&!isAdmin())teacher().coaching=f.coaching.value.trim();if(isStudent())me().phone=f.phone.value;db.settings.language=f.language.value;if(f.grading)db.settings.grading=f.grading.value;if(isAdmin()){db.settings.coaching=f.coaching.value;db.settings.uploadLimit=Number(f.uploadLimit.value);db.settings.extensions=f.extensions.value.toLowerCase().replaceAll(' ','');db.settings.grace=Number(f.grace.value);}save('Edit','settings',currentUser());render();toast(t('Settings saved'));}catch(err){$('#settings-error').textContent=err.message;}};
if($('#appearance-form'))$('#appearance-form').onsubmit=ev=>{ev.preventDefault();db.settings.theme=ev.currentTarget.theme.value;db.settings.motion=!ev.currentTarget.reduced.checked;persist(db);render();toast(t('Settings saved'));};
if($('#notifications-form'))$('#notifications-form').onsubmit=ev=>{ev.preventDefault();db.preferences[currentUser()]={...db.preferences[currentUser()]};for(const k of ['messages','notices','fees','attendance'])db.preferences[currentUser()][k]=ev.currentTarget.elements[k].checked;persist(db);toast(t('Settings saved'));};
if($('#password-form'))$('#password-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,a=db.accounts.find(a=>a.id===session.accountId);if(!a||await passwordHash(f.current.value,a.salt)!==a.hash){$('#password-error').textContent=db.settings.language==='bn'?'বর্তমান পাসওয়ার্ড ভুল।':'Current password is incorrect.';return;}if(f.password.value.length<8){$('#password-error').textContent=db.settings.language==='bn'?'কমপক্ষে ৮ অক্ষর দিন।':'Use at least 8 characters.';return;}a.hash=await passwordHash(f.password.value,a.salt);save('Change password','accounts',a.id);f.reset();toast(t('Settings saved'));};
if($('#backup-import'))$('#backup-import').onchange=ev=>importBackup(ev.target.files[0]);
}
async function featureAction(action){
const [a,b,c,d]=action.split(':');
try{
switch(a){
case 'close':if(voiceRecorder?.state==='recording'){voiceRecorder.stop();}closeModal();break;
case 'voice':await voiceRecord(b);break;
case 'switch':switchWorkspace();break;
case 'logout':closeModal();session=null;sessionStorage.setItem('sl-session','null');render();break;
case 'demo':{let teacherId=$('[name=demoTeacher]')?.value||'t1',studentId=$('[name=demoStudent]')?.value||db.students.find(s=>s.status==='Active')?.id;const s=db.students.find(x=>x.id===studentId);if(b==='student'&&!s){toast(t('No records yet'));break;}if(b==='student')teacherId=s.teacherId;const tchr=db.teachers.find(t=>t.id===teacherId);if(b!=='admin'&&(!tchr||tchr.status==='Suspended')){toast(t('Suspended'),true);break;}closeModal();setSession({role:b,id:b==='admin'?'admin':b==='student'?studentId:teacherId,teacherId:b==='admin'?null:teacherId,demo:true});break;}
case 'return-admin':closeModal();setSession({role:'admin',id:'admin',teacherId:null,demo:true});break;
case 'create':if(canEditEntity(b))editRecord(b);break;
case 'edit':editRecord(b,c);break;
case 'delete':removeRecord(b,c);break;
case 'archive':removeRecord(b,c,true);break;
case 'detail':detail(b,c);break;
case 'profile':profile(b);break;
case 'combined-report':combinedReport(b);break;
case 'student-import':bulkStudents();break;
case 'student-template':download('students-template.csv',csv([['name','studentId','grade','roll','guardian','guardianPhone','batchIds','phone','address'],['Sample Student','SL-2001','12','13','Sample Guardian','01700000000',batches()[0]?.id||'','','Dhaka']]),'text/csv');break;
case 'batch-students':go('students');batchFilter=b;render();break;
case 'att-batch':attBatch=b;go('attendance');break;
case 'mark':if(isStudent())break;attDraft[b]=c;$$('[data-student="'+b+'"] button').forEach(el=>el.classList.toggle('selected',el.classList.contains(c)));break;
case 'att-all':if(isStudent())break;students().filter(s=>s.batchIds.includes(attBatch)).forEach(s=>attDraft[s.id]='Present');$$('.status-buttons button').forEach(el=>el.classList.toggle('selected',el.classList.contains('Present')));break;
case 'att-save':saveAttendance();break;
case 'att-history':attendanceHistory();break;
case 'assignment':assignmentDetail(b);break;
case 'review':reviewSubmission(b);break;
case 'exam':examDetail(b);break;
case 'report':reportCard(b,c);break;
case 'publish-exam':{if(isStudent())break;const ex=own('exams').find(x=>x.id===b);if(!ex)break;if(ex.status!=='Published'&&!own('marks').some(m=>m.examId===b)){toast(db.settings.language==='bn'?'আগে নম্বর সংরক্ষণ করুন।':'Save marks before publishing.',true);break;}const before=structuredClone(ex);ex.status=ex.status==='Published'?'Draft':'Published';save('Edit','exams',b,before);if(ex.status==='Published')queueForRecord('exams',ex);closeModal();render();toast(t(ex.status));break;}
case 'question-add':syncQuestions();questionDraft.push({id:uid(),text:'',options:['','','',''],answer:0,topic:''});renderQuestionEditors();break;
case 'question-remove':syncQuestions();questionDraft.splice(Number(b),1);renderQuestionEditors();break;
case 'quiz-start':startQuiz(b);break;
case 'quiz-review':quizReview(b);break;
case 'quiz-analytics':quizAnalytics(b);break;
case 'fee-tab':tab=b;render();break;
case 'pay-for':editRecord('payments');if($('[name=studentId]')){$('[name=studentId]').value=b;const s=students().find(x=>x.id===b);$('[name=batchId]').value=s.batchIds[0];}break;
case 'receipt':receipt(b);break;
case 'calendar-prev':if(calendarMode==='week')calendarDate.setDate(calendarDate.getDate()-7);else calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1);render();break;
case 'calendar-next':if(calendarMode==='week')calendarDate.setDate(calendarDate.getDate()+7);else calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1);render();break;
case 'calendar-today':calendarDate=new Date();render();break;
case 'calendar-mode':calendarMode=b;render();break;
case 'chat':chatStudent=b;render();break;
case 'group-mode':if(!isStudent()){const batch=batches().find(x=>x.id===b);if(batch){const before=structuredClone(batch);batch.discussion=!batch.discussion;save('Edit','batches',b,before);render();}}break;
case 'message-edit':{const msg=own('messages').find(m=>m.id===b&&m.sender===session.id);if(!msg||Date.now()-new Date(msg.created).getTime()>=900000)break;modal('Edit','<form id="message-edit-form">'+field('message','Messages','textarea',msg.text,[],true,true)+'<button class="btn primary section-gap" type="submit">'+e('Save')+'</button></form>');$('#message-edit-form').onsubmit=ev=>{ev.preventDefault();const before=structuredClone(msg);msg.text=ev.currentTarget.message.value;msg.edited=true;save('Edit','messages',b,before);closeModal();render();};break;}
case 'message-delete':{const msg=own('messages').find(m=>m.id===b&&m.sender===session.id);if(!msg||Date.now()-new Date(msg.created).getTime()>=900000)break;confirmAction('Delete',()=>{db.messages=db.messages.filter(m=>m.id!==b);save('Delete','messages',b,msg);});break;}
case 'settings-tab':settingsTab=b;render();break;
case 'features':teacherFeatures(b);break;
case 'suspend':if(isAdmin()){const r=db.teachers.find(x=>x.id===b);if(r){const before=structuredClone(r);r.status=r.status==='Suspended'?'Active':'Suspended';save('Edit','teachers',b,before);render();}}break;
case 'impersonate':if(isAdmin()&&db.teachers.some(x=>x.id===b)){save('View as teacher','teachers',b);setSession({role:'teacher',id:b,teacherId:b,demo:true,impersonating:true});}break;
case 'audit-detail':if(isAdmin()){const r=db.audit.find(x=>x.id===b);modal('Audit log','<pre class="detail-text">'+esc(JSON.stringify(r,null,2))+'</pre>',btn('Close','close'));}break;
case 'guardian-refresh':if(!isStudent()){for(const s of students()){const key='summary:'+s.id+':'+today();if(!db.queue.some(q=>q.dedupe===key))db.queue.unshift({id:uid(),teacherId:session.teacherId,studentId:s.id,type:'General',text:guardianSummary(s),created:new Date().toISOString(),status:'Not sent',dedupe:key});}save('Create','queue','daily-summary');render();toast(t('Saved successfully'));}break;
case 'queue':{const q=own('queue').find(q=>q.id===b);if(q)modal('Preview message','<p class="hint">'+e('Not sent')+' · '+esc(db.students.find(s=>s.id===q.studentId)?.guardianPhone)+'</p><p class="detail-text">'+esc(q.text)+'</p>',btn('Close','close'));break;}
case 'ai-preview':aiPreview(b);break;
case 'file':{const accessible=Object.keys(db).filter(k=>Array.isArray(db[k])&&['students','assignments','submissions','materials','notices','messages'].includes(k)).flatMap(k=>visible(k)).flatMap(r=>[...(r.files||[]),...(r.feedbackFiles||[])]).some(f=>f.id===b);if(!accessible&&!isAdmin())break;const file=await getFile(b);if(file){const url=URL.createObjectURL(file);let media='';if(['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))media='<img src="'+url+'" style="width:100%;max-height:65vh;object-fit:contain" alt="'+esc(file.name)+'">';else if(file.type==='application/pdf')media='<iframe title="'+e('Attachment')+'" src="'+url+'" style="width:100%;height:60vh;border:0"></iframe>';else if(file.type.startsWith('audio/'))media='<audio controls src="'+url+'" style="width:100%"></audio>';else if(file.type.startsWith('video/'))media='<video controls src="'+url+'" style="width:100%"></video>';else media='<p class="detail-text">'+esc(file.name)+'</p>';modal('Attachment',media,'<a class="btn primary" href="'+url+'" download="'+esc(file.name)+'">'+e('Download')+'</a>'+btn('Close','close'),true);}else toast(db.settings.language==='bn'?'ফাইল পাওয়া যায়নি।':'File not found.',true);break;}
case 'print':window.print();break;
case 'print-attendance':{const body=$('#history-results')?.innerHTML;if(body){modal('Attendance history','<div class="report"><h1>'+esc(teacher().coaching)+'</h1><h3>'+e('Attendance history')+'</h3>'+body+'</div>',btn('Print report','print','','download')+btn('Close','close'),true);}break;}
case 'export':exportEntity(b);break;
case 'zip-submissions':{if(isStudent())break;const entries=[];for(const sub of own('submissions').filter(s=>s.assignmentId===b)){const prefix=studentName(sub.studentId).replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+sub.studentId;entries.push({name:prefix+'/answer.txt',data:sub.text+'\n\nFeedback: '+(sub.feedback||'')+'\nMarks: '+(sub.marks??'Not graded')});for(const metadata of sub.files||[]){const file=await getFile(metadata.id);if(file)entries.push({name:prefix+'/'+metadata.name,data:file});}}const {zipFiles}=await import('./zip.js');download('submissions-'+b+'.zip',await zipFiles(entries));break;}
case 'export-submissions':{if(isStudent())break;const rows=own('submissions').filter(s=>s.assignmentId===b);download('submissions.csv',csv([['Student','Status','Answer','Marks','Feedback','Submitted'],...rows.map(s=>[studentName(s.studentId),s.status,s.text,s.marks,s.feedback,s.submittedAt])]),'text/csv');break;}
case 'backup-export':await exportBackup();break;
case 'notifications':notificationsModal();break;
case 'search':searchModal();break;
default:break;
}
}catch(err){toast(err.message,true);console.error(err);}
}
function exportEntity(entity){let rows=[];if(entity==='students')rows=[['ID','Name','Grade','Batches','Guardian','WhatsApp','Status'],...(isStudent()?[me()]:filtered(own('students'))).map(s=>[s.studentId,s.name,s.grade,s.batchIds.map(batchName).join('; '),s.guardian,s.guardianPhone,s.status])];if(entity==='attendance'){const from=$('[name=from]')?.value||'',to=$('[name=to]')?.value||'9999';rows=[['Student','Batch','Date','Status'],...visible('attendance').filter(a=>a.date>=from&&a.date<=to&&(!attBatch||a.batchId===attBatch)).map(a=>[studentName(a.studentId),batchName(a.batchId),a.date,a.status])];}if(entity==='payments')rows=[['Student','Batch','Month','Amount','Method','Reference','Date'],...visible('payments').filter(p=>p.month===feeMonth).map(p=>[studentName(p.studentId),batchName(p.batchId),p.month,p.amount,p.method,p.reference,p.date])];if(entity==='audit'&&isAdmin())rows=[['Actor','Action','Entity','Record','Time'],...db.audit.map(a=>[a.actor,a.action,a.entity,a.recordId,a.created])];if(entity==='analytics'&&!isStudent())rows=[['Student','Attendance %','Outstanding fee'],...students().map(s=>[s.name,attendanceRate(own('attendance').filter(a=>a.studentId===s.id)),outstanding(db,s.id)])];if(rows.length)download(entity+'-'+today()+'.csv',csv(rows),'text/csv;charset=utf-8');}
function scopedBackup(){const result=structuredClone(db);if(!isAdmin()){for(const key of Object.keys(result)){if(Array.isArray(result[key]))result[key]=key==='teachers'?result[key].filter(x=>x.id===session.teacherId):key==='plans'?result[key]:key==='accounts'?result[key].filter(x=>x.teacherId===session.teacherId):key==='readNotices'?[]:visible(key);}result.preferences={[currentUser()]:db.preferences[currentUser()]||{}};if(isStudent()){result.accounts=[];result.students=result.students.filter(s=>s.id===session.id);result.audit=[];result.queue=[];}}return result;}
async function exportBackup(){toast(db.settings.language==='bn'?'ব্যাকআপ তৈরি হচ্ছে…':'Preparing backup…');const records=scopedBackup(),ids=new Set(Object.values(records).filter(Array.isArray).flat().flatMap(r=>[...(r.files||[]),...(r.feedbackFiles||[])]).map(f=>f.id));const files=[];for(const {id,file} of await getAllFiles()){if(!ids.has(id))continue;const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));files.push({id,name:file.name,type:file.type,data:btoa(binary)});}download('science-lab-backup-'+today()+'.json',JSON.stringify({format:'science-lab-backup-v1',scope:isAdmin()?'platform':isStudent()?'student':'teacher',teacherId:session.teacherId,records,files},null,2),'application/json');}
async function importBackup(file){if(!file||isStudent())return;if(!session.demo){toast('Cloud account restoration requires an administrator migration.',true);return;}try{if(file.size>100*1048576)throw Error('Backup exceeds 100 MB.');const backup=JSON.parse(await file.text());if(backup.format!=='science-lab-backup-v1'||backup.records?.version!==1||!Array.isArray(backup.records.students)||!Array.isArray(backup.files))throw Error(db.settings.language==='bn'?'ব্যাকআপ ফাইলটি সঠিক নয়।':'Invalid backup file.');if(!isAdmin()&&(backup.scope!=='teacher'||backup.teacherId!==session.teacherId))throw Error(db.settings.language==='bn'?'এই ব্যাকআপ আপনার ওয়ার্কস্পেসের নয়।':'Backup does not belong to this workspace.');for(const key of Object.keys(db)){if(Array.isArray(db[key])&&!Array.isArray(backup.records[key]))throw Error('Missing data: '+key);}modal('Import backup','<p class="hint warning">'+(db.settings.language==='bn'?'বর্তমান তথ্য প্রতিস্থাপিত হবে। আগে ব্যাকআপ ডাউনলোড করে নিন।':'Existing records will be replaced. Export a backup first.')+'</p><p class="detail-text">'+backup.records.students.length+' '+e('Students')+' · '+backup.files.length+' '+e('Selected files')+'</p>',btn('Cancel','close')+'<button class="btn primary" id="restore-backup">'+e('Restore')+'</button>');$('#restore-backup').onclick=async()=>{try{const next=structuredClone(db);if(isAdmin()){if(backup.scope!=='platform')throw Error('Use a platform backup in the administrator workspace.');Object.assign(next,backup.records);}else{for(const key of Object.keys(next)){if(Array.isArray(next[key])&&!['plans','teachers','readNotices'].includes(key))next[key]=next[key].filter(r=>r.teacherId!==session.teacherId).concat(backup.records[key].filter(r=>r.teacherId===session.teacherId));}const teacherCopy=backup.records.teachers.find(t=>t.id===session.teacherId);if(teacherCopy){const original=next.teachers.find(t=>t.id===session.teacherId);original.name=teacherCopy.name;original.coaching=teacherCopy.coaching;}}for(const f of backup.files){if(typeof f.id!=='string'||typeof f.data!=='string')throw Error('Invalid attachment.');const bytes=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));await putFile(new File([bytes],f.name,{type:f.type}),f.id);}persist(next);db=next;save('Restore','backup','local');closeModal();render();toast(t('Saved successfully'));}catch(err){toast(err.message,true);}};}catch(err){toast(err.message,true);}}
function notificationsModal(){const pref=db.preferences[currentUser()]||{},items=[];visible('assignments').filter(a=>a.status==='Published').forEach(a=>items.push({title:a.title,subtitle:t('Assignments')+' · '+date(a.deadline),action:'assignment:'+a.id}));visible('exams').filter(a=>a.status==='Published'||a.date>=today()).forEach(a=>items.push({title:a.title,subtitle:t('Exams')+' · '+date(a.date),action:'exam:'+a.id}));if(pref.notices!==false)visible('notices').filter(n=>!n.expires||n.expires>=today()).forEach(n=>items.push({title:n.title,subtitle:t('Notices'),action:'detail:notices:'+n.id}));modal('Notifications',items.map(x=>'<div class="switch-row"><span>'+esc(x.title)+'<p>'+esc(x.subtitle)+'</p></span>'+btn('Open',x.action,'small')+'</div>').join('')||empty(),btn('Close','close'));}
function searchModal(){modal('Search','<input id="global-search" class="search-input" style="width:100%" placeholder="'+e('Search anything…')+'" aria-label="'+e('Search')+'"><div id="search-results" class="section-gap"></div>');$('#global-search').focus();$('#global-search').oninput=ev=>{const q=ev.target.value.trim().toLowerCase();const results=Object.entries(labels).filter(([p,label])=>allowed(p)&&(label.toLowerCase().includes(q)||t(label).includes(q))).map(([p,label])=>({title:t(label),action:'go:'+p}));if(q){for(const entity of ['students','assignments','materials','exams','notices']){if(!allowed(entity)&&entity!=='students')continue;const rows=entity==='students'&&isStudent()?[me()]:visible(entity);rows.filter(r=>(r.name||r.title||'').toLowerCase().includes(q)).slice(0,5).forEach(r=>results.push({title:r.name||r.title,action:entity==='students'?'profile:'+r.id:entity==='assignments'?'assignment:'+r.id:entity==='exams'?'exam:'+r.id:'detail:'+entity+':'+r.id}));}}$('#search-results').innerHTML=results.slice(0,15).map(x=>'<button class="nav-item" data-action="'+x.action+'">'+icon('arrow')+esc(x.title)+'</button>').join('')||empty();};$('#global-search').dispatchEvent(new Event('input'));}
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();if(session)searchModal();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'dashboard';if(page!==next&&!$('dialog')?.dataset.quiz){page=next;filter='';batchFilter='all';statusFilter='all';render();}});
window.addEventListener('storage',ev=>{if(ev.key==='science-lab-v1'&&!$('dialog')){db=load();render();}});

let voiceRecorder=null,voiceStream=null;
async function voiceRecord(target){if(!navigator.mediaDevices?.getUserMedia){toast(db.settings.language==='bn'?'এই ব্রাউজারে রেকর্ডিং সমর্থিত নয়।':'Recording is unavailable in this browser.',true);return;}if(voiceRecorder?.state==='recording'){voiceRecorder.stop();return;}try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];voiceRecorder=new MediaRecorder(voiceStream);voiceRecorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data);};voiceRecorder.onstop=()=>{voiceStream.getTracks().forEach(t=>t.stop());const file=new File(chunks,'voice-'+Date.now()+'.webm',{type:voiceRecorder.mimeType||'audio/webm'}),input=document.querySelector('[name="'+target+'"]');if(input){const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files;toast(db.settings.language==='bn'?'ভয়েস যুক্ত হয়েছে। সংরক্ষণ বা পাঠান চাপুন।':'Voice attached. Save or send to finish.');}const button=$('[data-action="voice:'+target+'"]');if(button){button.innerHTML=icon('clock')+' '+e('Record voice');button.classList.remove('danger');}};voiceRecorder.start();const button=$('[data-action="voice:'+target+'"]');if(button){button.textContent=t('Stop recording');button.classList.add('danger');}}catch(err){voiceStream?.getTracks().forEach(t=>t.stop());toast(db.settings.language==='bn'?'মাইক্রোফোন ব্যবহার করা যায়নি। ফাইল যুক্ত করতে পারেন।':'Microphone unavailable. You can attach an audio file instead.',true);}}
function evaluateLocalLifecycle(){if(session&&!session.demo)return;let changed=false;for(const teacher of db.teachers){const expiry=new Date(teacher.expiry+'T23:59:59');expiry.setDate(expiry.getDate()+Number(db.settings.grace||0));if(teacher.status!=='Suspended'&&Date.now()>expiry.getTime()){teacher.status='Suspended';db.audit.unshift({id:uid(),teacherId:teacher.id,actor:'Local system',action:'Suspend',entity:'teachers',recordId:teacher.id,created:new Date().toISOString()});changed=true;}}if(changed)persist(db);}
evaluateLocalLifecycle();

function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('Unclosed CSV quote');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function bulkStudents(){if(isStudent()||isAdmin())return;modal('Import students','<p class="hint">'+(db.settings.language==='bn'?'CSV টেমপ্লেট পূরণ করুন। batchIds-এ ব্যাচের ID দিন; একাধিক হলে | দিয়ে আলাদা করুন।':'Fill in the CSV template. Use batch IDs in batchIds, separated by |.')+'</p>'+btn('Download template','student-template','','download')+'<div class="hint section-gap">'+batches().map(b=>esc(b.id)+' = '+esc(b.name)).join('<br>')+'</div><label class="field section-gap"><span>CSV</span><input type="file" id="student-csv" accept=".csv,text/csv"></label><div class="error" id="import-error"></div><div id="import-preview"></div>',btn('Close','close'),true);$('#student-csv').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>2097152)throw Error('CSV maximum: 2 MB');const [headers,...rows]=parseCSV((await file.text()).replace(/^\uFEFF/,'')),keys=headers.map(v=>v.trim());for(const key of ['name','studentId','grade','guardian','guardianPhone','batchIds'])if(!keys.includes(key))throw Error('Missing column: '+key);if(!rows.length||rows.length>200)throw Error('Import 1–200 students at a time.');const additions=rows.map((values,i)=>{const r=Object.fromEntries(keys.map((k,j)=>[k,(values[j]||'').trim()]));return {id:uid(),teacherId:session.teacherId,name:r.name,studentId:r.studentId,grade:r.grade,roll:Number(r.roll)||students().length+i+1,guardian:r.guardian,guardianPhone:r.guardianPhone,batchIds:r.batchIds.split('|').map(x=>x.trim()),phone:r.phone||'',address:r.address||'',status:'Active',joined:today()};});const originalStudents=db.students;try{db.students=[...originalStudents];for(const r of additions){if(!r.name||!r.guardian||!r.grade)throw Error('Name, grade and guardian are required.');validateRecord('students',r,null);db.students.push(r);}}finally{db.students=originalStudents;}$('#import-error').textContent='';$('#import-preview').innerHTML='<p class="hint section-gap">'+num(additions.length)+' '+e('Students')+'</p><div class="table-wrap"><table><thead><tr><th>'+e('Name')+'</th><th>'+e('Student ID')+'</th><th>'+e('Batch')+'</th></tr></thead><tbody>'+additions.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+esc(r.studentId)+'</td><td>'+r.batchIds.map(batchName).map(esc).join('<br>')+'</td></tr>').join('')+'</tbody></table></div><button id="confirm-student-import" class="btn primary section-gap">'+e('Import students')+'</button>';$('#confirm-student-import').onclick=async ev=>{ev.currentTarget.disabled=true;const credentials=[],accounts=[];try{for(const r of additions){const password='Lab!'+crypto.getRandomValues(new Uint32Array(2)).join('').slice(0,10),salt=uid();accounts.push({id:uid(),role:'student',ref:r.id,teacherId:session.teacherId,username:r.studentId,salt,hash:await passwordHash(password,salt),forceReset:true});credentials.push([r.name,r.studentId,password]);}db.students.push(...additions);db.accounts.push(...accounts);save('Import students','students',additions.length);closeModal();render();modal('Temporary credentials','<div class="table-wrap"><table><thead><tr><th>'+e('Name')+'</th><th>'+e('Username')+'</th><th>'+e('Password')+'</th></tr></thead><tbody>'+credentials.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><button class="btn primary section-gap" id="download-credentials">'+e('Export CSV')+'</button>',btn('Close','close'),true);$('#download-credentials').onclick=()=>download('student-credentials.csv',csv([['Name','Username','Temporary password'],...credentials]),'text/csv');}catch(err){toast(err.message,true);}};}catch(err){$('#import-error').textContent=err.message;$('#import-preview').innerHTML='';}};}
function combinedReport(studentId){if(isStudent()&&studentId!==session.id)return;const s=own('students').find(s=>s.id===studentId);if(!s)return;const candidates=visible('exams').filter(e=>e.status==='Published'&&s.batchIds.includes(e.batchId)).sort((a,b)=>b.date.localeCompare(a.date)),selected=[],subjects=new Set();for(const ex of candidates){if(subjects.has(ex.subject))continue;const mark=own('marks').find(m=>m.examId===ex.id&&m.studentId===studentId);if(mark){selected.push({exam:ex,mark});subjects.add(ex.subject);}}if(!selected.length){toast(t('No records yet'));return;}const achieved=selected.reduce((n,r)=>n+r.mark.marks,0),total=selected.reduce((n,r)=>n+r.exam.total,0);modal('Combined report','<div class="report"><div class="card-top"><div><h1>'+esc(teacher().coaching)+'</h1><p>'+e('Combined report')+'</p></div><img src="favicon.svg" alt="" width="42"></div><hr style="margin:25px 0;border:0;border-top:2px solid #16856e"><h2>'+esc(s.name)+'</h2><p style="margin:10px 0">'+esc(s.studentId)+' · '+e('Grade')+' '+esc(s.grade)+'</p><p>'+e('Latest published exam per subject')+'</p><table><thead><tr>'+['Subject','Exams','Date','Marks','Total marks','Grade'].map(x=>'<th>'+e(x)+'</th>').join('')+'</tr></thead><tbody>'+selected.map(({exam,mark})=>'<tr><td>'+esc(exam.subject)+'</td><td>'+esc(exam.title)+'</td><td>'+date(exam.date)+'</td><td>'+num(mark.marks)+'</td><td>'+num(exam.total)+'</td><td>'+grade(mark.marks/exam.total*100,db.settings.grading)+'</td></tr>').join('')+'</tbody></table><h3>'+e('Total')+': '+num(achieved)+' / '+num(total)+' · '+grade(achieved/total*100,db.settings.grading)+'</h3><p style="margin-top:55px;border-top:1px solid #bbb;padding-top:12px;width:210px">'+e('Signature')+' · '+esc(teacher().name)+'</p></div>',btn('Print report','print','','download')+btn('Close','close'),true);}
function recipientName(id){if(id?.startsWith('group-'))return batchName(id.slice(6));return isStudent()?teacher().name:studentName(id);}

let liveProfile=null,authMode='login',authMessage='',authBusy=false,cloudState='idle';
const bilingual=(en,bn)=>db.settings.language==='bn'?bn:en;
const localLogin=renderLogin;
renderLogin=function(){
 const reset=authMode==='reset',forgot=authMode==='forgot';
 $('#app').innerHTML='<main class="login"><section class="login-story"><div class="brand"><img src="favicon.svg" alt=""><div><strong>Science Lab.</strong><small>Coaching workspace</small></div></div><div><div class="eyebrow">LEARN · EXPERIMENT · GROW</div><h1>'+bilingual('Your next discovery starts here.','তোমার নতুন আবিষ্কার শুরু হোক এখানেই।')+'</h1><p>'+bilingual('One workspace. Your teachers, classes and progress.','শিক্ষক, ক্লাস আর শেখার অগ্রগতি—সব এক জায়গায়।')+'</p><button type="button" class="lab-art" data-action="focus-login" aria-label="'+bilingual('Go to login form','লগইন ফর্মে যাও')+'"><i class="orbit"></i><i class="orbit two"></i><i class="orbit three"></i><img src="favicon.svg" alt=""></button><span class="lab-hint">'+bilingual('Tap the flask to sign in','লগইন করতে ফ্লাস্কে চাপ দাও')+'</span></div><p>'+bilingual('Private accounts · Connected learning','ব্যক্তিগত অ্যাকাউন্ট · একসাথে শেখা')+'</p></section><section class="login-form"><div class="login-box"><div class="eyebrow">SCIENCE LAB</div><h2>'+bilingual(reset?'Choose a new password':forgot?'Forgot your password?':'Welcome to your lab.',reset?'নতুন পাসওয়ার্ড দাও':forgot?'পাসওয়ার্ড ভুলে গেছ?':'তোমার ল্যাবে স্বাগতম।')+'</h2><p class="subtitle">'+bilingual(reset?'Use at least 12 characters.':forgot?'We will email a reset link. Open it in this same browser.':'Sign in with the email and password provided by your administrator or teacher.',reset?'কমপক্ষে ১২ অক্ষরের পাসওয়ার্ড ব্যবহার করো।':forgot?'ইমেইলে reset link যাবে। এই একই ব্রাউজারে লিংকটি খুলবে।':'অ্যাডমিন বা শিক্ষকের দেওয়া ইমেইল ও পাসওয়ার্ড দিয়ে প্রবেশ করো।')+'</p><form id="secure-auth-form">'+(!reset?field('email','Email','email','',[],true,true):'')+(!forgot?field('password',reset?'New password':'Password','password','',[],true,true):'')+(reset?field('confirm','Confirm password','password','',[],true,true):'')+'<div id="auth-error" class="error" role="alert">'+esc(authMessage)+'</div><button type="submit" class="btn primary" '+(authBusy?'disabled':'')+'>'+bilingual(reset?'Save password':forgot?'Send reset link':'Log in',reset?'পাসওয়ার্ড সংরক্ষণ':forgot?'Reset link পাঠাও':'লগইন')+icon('arrow')+'</button></form>'+(!reset?'<button class="btn ghost section-gap" data-action="auth-mode:'+(forgot?'login':'forgot')+'">'+bilingual(forgot?'Back to login':'Forgot password?',forgot?'লগইনে ফিরে যাও':'পাসওয়ার্ড ভুলে গেছ?')+'</button>':btn('Sign out','logout','section-gap'))+(!reset?'<div class="demo-divider">'+bilingual('Explore a separate demo — sample data only','আলাদা ডেমো দেখো—শুধু নমুনা তথ্য')+'</div><div class="demo-roles">'+btn('Teacher','demo:teacher')+btn('Student','demo:student')+btn('Super Admin','demo:admin')+'</div>':'')+'<button class="btn ghost section-gap" data-action="language">'+(db.settings.language==='en'?'বাংলায় দেখুন':'English')+'</button></div></section></main>';
 const f=$('#secure-auth-form');if(f.email)f.email.autocomplete='username';if(f.password){f.password.autocomplete=reset?'new-password':'current-password';if(reset)f.password.minLength=12;}
 f.onsubmit=async ev=>{ev.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;$('#auth-error').textContent='';
 try{
  if(forgot){await cloud.forgot(f.email.value.trim());$('#auth-error').textContent=bilingual('If the address is registered, a reset link will arrive. Check your spam folder.','ঠিকানাটি নিবন্ধিত হলে reset link যাবে। Spam folder-ও দেখবে।');return;}
  if(reset){if(f.password.value!==f.confirm.value)throw Error(bilingual('Passwords do not match.','দুই পাসওয়ার্ড মিলছে না।'));await acceptCloud(await cloud.password(f.password.value));return;}
  await acceptCloud(await cloud.login(f.email.value.trim(),f.password.value));
 }catch(error){$('#auth-error').textContent=error.message;}finally{button.disabled=false;}};
};
async function acceptCloud(result){
 liveProfile=result.profile;
 if(result.profile.mustChangePassword||sessionStorage.getItem('sl-password-recovery')==='1'){session=null;authMode='reset';authMessage='';renderLogin();return;}
 db=result.db;cloud.attach(db);globalThis.scienceLabFileMode=true;globalThis.scienceLabCurrentDB=()=>db;
 authMode='login';authMessage='';session={role:liveProfile.role,id:liveProfile.id,teacherId:liveProfile.teacherId,accountId:liveProfile.id,demo:false,impersonating:!!liveProfile.viewing};
 page='dashboard';location.hash='dashboard';closeModal();render();
}
async function refreshCloud(){const result=await cloud.refresh();if(result.profile.mustChangePassword)return acceptCloud(result);db=result.db;liveProfile=result.profile;render();}
function showCredentials(result){modal('Temporary credentials','<p class="hint">'+bilingual('Share these details directly with the account owner. A new password is required at first login.','এই তথ্য সরাসরি অ্যাকাউন্টের মালিককে দাও। প্রথম লগইনে নতুন পাসওয়ার্ড দিতে হবে।')+'</p><div class="credential">Email: '+esc(result.email)+'<br>'+e('Password')+': '+esc(result.password)+'</div>',btn('Close','close'));}
const originalFeatureAction=featureAction;
featureAction=async function(action){
 const [a,b]=action.split(':');
 if(a==='auth-mode'){authMode=b;authMessage='';renderLogin();return;}
 if(a==='logout'||a==='switch'&&!session?.demo){await cloud.logout();globalThis.scienceLabFileMode=false;liveProfile=null;session=null;sessionStorage.removeItem('sl-session');db=load();authMode='login';authMessage='';$('#overlay').innerHTML='';render();return;}
 if(a==='demo'){if(cloud.isReal())await cloud.logout();globalThis.scienceLabFileMode=false;liveProfile=null;if(!session?.demo)db=load();return originalFeatureAction(action);}
 if(session&&!session.demo){
  if(a==='impersonate'||a==='return-admin'){toast(bilingual('Use a separate teacher login to access a classroom.','ক্লাসরুমে প্রবেশ করতে আলাদা teacher login ব্যবহার করো।'),true);return;}
  if(a==='student-import'){realStudentImport();return;}
  if(a==='refresh-cloud'){try{await refreshCloud();toast(bilingual('Up to date.','তথ্য আপডেট হয়েছে।'));}catch(err){toast(err.message,true);}return;}
 }
 return originalFeatureAction(action);
};
const originalBindFeatures=bindFeatures;
bindFeatures=function(){originalBindFeatures();
 if(!session?.demo&&$('#password-form'))$('#password-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;try{if(f.password.value.length<12)throw Error('Use at least 12 characters.');await cloud.password(f.password.value,f.current.value);f.reset();toast(bilingual('Password updated.','পাসওয়ার্ড বদলানো হয়েছে।'));}catch(err){$('#password-error').textContent=err.message;}finally{button.disabled=false;}};
 if(!session?.demo&&$('#backup-import')){$('#backup-import').parentElement.hidden=true;}
};
const originalSettings=settingsPage;
settingsPage=function(){let html=originalSettings();if(session&&!session.demo){html=html.replace('This is a local demo. Production account security and data isolation require the future backend.','Your login is secured by Supabase. Only your administrator can manage account access.').replace('এটি স্থানীয় ডেমো। আসল অ্যাকাউন্ট নিরাপত্তা ও ডেটা বিচ্ছিন্নতা ব্যাকএন্ড যুক্ত করার পর চালু হবে।','Supabase দিয়ে লগইন সুরক্ষিত। শুধু তোমার অ্যাডমিন অ্যাকাউন্টের অনুমতি নিয়ন্ত্রণ করতে পারেন।');}return html;};
const originalRender=render;
render=function(){originalRender();if(!session)return;
 const label=$('.local-label');if(label)label.innerHTML='<i class="dot"></i>'+bilingual(session.demo?'Demo · sample data':'Cloud workspace',session.demo?'ডেমো · নমুনা তথ্য':'ক্লাউড ওয়ার্কস্পেস');
 const footer=$('.page-footer span:last-child');if(footer)footer.textContent=bilingual(session.demo?'Demo data stays in this browser':'Your data is stored securely online',session.demo?'ডেমোর তথ্য এই ব্রাউজারে থাকে':'তথ্য অনলাইনে সুরক্ষিতভাবে সংরক্ষিত');
 if(!session.demo){const switcher=$('[data-action=switch]');if(switcher)switcher.innerHTML=icon('logout')+e('Sign out');$('.top-actions')?.insertAdjacentHTML('afterbegin','<button class="btn ghost small" data-action="refresh-cloud" id="cloud-status">'+bilingual('Refresh','আপডেট')+'</button>');}
 if(session.demo)$('.content')?.insertAdjacentHTML('afterbegin','<div class="demo-banner">'+bilingual('DEMO — sample accounts and data. Changes here do not affect real accounts.','ডেমো — নমুনা অ্যাকাউন্ট ও তথ্য। এখানে বদলালে real account বদলাবে না।')+'</div>');
};
const originalToast=toast;
toast=function(message,error=false){if(session&&!session.demo&&!error&&[t('Saved successfully'),t('Settings saved')].includes(message))message=bilingual('Saving to cloud…','ক্লাউডে সংরক্ষণ হচ্ছে…');originalToast(message,error);};
async function realStudentImport(){
 modal('Import students','<p class="hint">'+bilingual('CSV needs email, name, studentId, grade, guardian, guardianPhone and batchIds (separate batch IDs with |). Real login accounts will be created.','CSV-তে email, name, studentId, grade, guardian, guardianPhone ও batchIds লাগবে। একাধিক batch ID | দিয়ে আলাদা করো।')+'</p><input id="real-import" type="file" accept=".csv"><div id="real-import-error" class="error"></div><div id="real-import-preview"></div>',btn('Close','close'),true);
 $('#real-import').onchange=async ev=>{try{
  const file=ev.target.files[0];if(!file)return;if(file.size>200000)throw Error('CSV limit: 200 KB');
  const [headers,...rows]=parseCSV((await file.text()).replace(/^\uFEFF/,''));const keys=headers.map(x=>x.trim());
  for(const key of ['email','name','studentId','grade','guardian','guardianPhone','batchIds'])if(!keys.includes(key))throw Error('Missing column: '+key);
  if(!rows.length||rows.length>50)throw Error('Import 1–50 students at a time.');
  const records=rows.map(values=>{const r=Object.fromEntries(keys.map((k,i)=>[k,values[i]||'']));return {...r,batchIds:r.batchIds.split('|').map(x=>x.trim()),status:'Active',roll:Number(r.roll)||1};});
  $('#real-import-preview').innerHTML='<p>'+records.length+' '+e('Students')+'</p><div class="detail-text">'+records.map(r=>esc(r.name)+' · '+esc(r.email)).join('<br>')+'</div><button class="btn primary section-gap" id="real-import-confirm">'+e('Import students')+'</button>';
  $('#real-import-confirm').onclick=async ev=>{ev.currentTarget.disabled=true;const results=[];let failure='';
   for(const record of records){try{results.push(await cloud.request('account',{role:'student',record}));}catch(err){failure=err.message;break;}}
   await refreshCloud();modal('Temporary credentials','<p class="hint">'+results.length+' '+bilingual('accounts created.','টি অ্যাকাউন্ট তৈরি হয়েছে।')+(failure?' '+esc(failure):'')+'</p><div class="detail-text">'+results.map(r=>esc(r.email)+' : '+esc(r.password)).join('<br>')+'</div>',btn('Close','close'),true);
  };
 }catch(err){$('#real-import-error').textContent=err.message;}};
}
function mergeCloudDB(next){for(const [key,value] of Object.entries(next)){if(Array.isArray(value)){const existing=new Map((db[key]||[]).map(r=>[r.id,r]));db[key]=value.map(r=>{const old=existing.get(r.id);if(old){for(const k of Object.keys(old))if(!(k in r))delete old[k];Object.assign(old,r);return old;}return r;});}else db[key]=value;}}
async function boot(){
 globalThis.scienceLabPersist=state=>cloud.persist(state);
 globalThis.scienceLabUpload=(file,id)=>cloud.upload(file,id);
 globalThis.scienceLabDownload=id=>cloud.file(id);
 globalThis.scienceLabAllFiles=()=>cloud.allFiles(db);
 window.addEventListener('sl-cloud-status',ev=>{cloudState=ev.detail.value;const el=$('#cloud-status');if(el)el.textContent=cloudState==='saving'?bilingual('Saving…','সংরক্ষণ হচ্ছে…'):cloudState==='error'?bilingual('Retry / refresh','আবার আপডেট'):bilingual('Synced · refresh','সংরক্ষিত · আপডেট');if(ev.detail.error)toast(ev.detail.error,true);});
 window.addEventListener('sl-cloud-reload',ev=>{if(session&&!session.demo){mergeCloudDB(ev.detail.db);if(!$('dialog')&&!document.activeElement?.matches('input,textarea,select'))render();}});
 window.addEventListener('sl-signed-out',()=>{session=null;globalThis.scienceLabFileMode=false;liveProfile=null;db=load();authMode='login';authMessage=bilingual('Please log in again.','আবার লগইন করো।');$('#overlay').innerHTML='';render();});
 window.addEventListener('sl-password-recovery',()=>{session=null;authMode='reset';renderLogin();});
 render();
 try{const restored=await cloud.restore();if(restored){if(new URLSearchParams(location.search).get('reset')==='1')sessionStorage.setItem('sl-password-recovery','1');if(!session?.demo)await acceptCloud(restored);}}
 catch(error){authMessage=error.message;if(!session)renderLogin();}
 // Explicit refresh is available while editing; automatic refresh never interrupts a form.
 setInterval(async()=>{if(!session||session.demo||cloud.busy()||$('dialog')||document.activeElement?.matches('input,textarea,select'))return;try{const result=await cloud.refresh();if(result.profile.mustChangePassword)return acceptCloud(result);db=result.db;render();}catch(error){toast(error.message,true);}},60000);
}

const demoStartQuiz=startQuiz;
startQuiz=async function(id){
 if(session?.demo)return demoStartQuiz(id);
 if(!isStudent())return;
 try{
  await cloud.flush();
  const started=await cloud.request('quiz-start',{quizId:id}),quiz=db.quizzes.find(q=>q.id===id);
  const key='sl-real-quiz-'+session.id+'-'+id;let draft=JSON.parse(localStorage.getItem(key)||'null')||{answers:{}};
  draft.end=started.result.end;const order=quiz.questions.map(q=>q.id);
  if(quiz.random&&!draft.order){for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}}draft.order||=order;
  modal(quiz.title,'<div class="quiz-timer">'+e('Time remaining')+' <strong id="quiz-timer"></strong></div>'+draft.order.map((qid,i)=>{const q=quiz.questions.find(q=>q.id===qid);return '<section class="quiz-question"><h3>'+(i+1)+'. '+esc(q.text)+'</h3>'+q.options.map((o,j)=>'<button class="quiz-option '+(draft.answers[q.id]===j?'selected':'')+'" data-q="'+q.id+'" data-answer="'+j+'"><span>'+String.fromCharCode(65+j)+'</span>'+esc(o)+'</button>').join('')+'</section>';}).join('')+'<div id="quiz-network-error" class="error"></div>','<button class="btn primary" id="finish-quiz">'+e('Submit quiz')+'</button>',true);
  $('dialog').dataset.quiz='true';$('dialog .modal-header [data-action=close]').hidden=true;
  const store=()=>localStorage.setItem(key,JSON.stringify(draft));store();
  $$('.quiz-option').forEach(b=>b.onclick=()=>{if(Date.now()>draft.end)return;draft.answers[b.dataset.q]=Number(b.dataset.answer);store();$$('[data-q="'+b.dataset.q+'"]').forEach(x=>x.classList.toggle('selected',x===b));});
  let sending=false;
  const finish=async()=>{if(sending)return;sending=true;$('#finish-quiz').disabled=true;clearInterval(quizInterval);
   try{const result=await cloud.request('quiz-submit',{quizId:id,answers:draft.answers});db=result.db;cloud.attach(db);localStorage.removeItem(key);delete $('dialog').dataset.quiz;closeModal();render();quizReview(id);}
   catch(error){$('#quiz-network-error').textContent=error.message;$('#finish-quiz').disabled=false;sending=false;}
  };
  $('#finish-quiz').onclick=finish;const tick=()=>{const remaining=Math.max(0,Math.ceil((draft.end-Date.now())/1000));$('#quiz-timer').textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(!remaining)finish();};tick();if(!sending)quizInterval=setInterval(tick,1000);
 }catch(error){toast(error.message,true);}
};

